insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('birch', 'Birch', -1, 0.88, 1.02, 1.05, 1, 0.96, 1.04, 1, false, 'Light and even-grained. The bowyer''s wood for a medium bow.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('pine', 'Pine', -3, 0.8, 1.2, 1.25, 0.9, 0.88, 1.06, 0.95, false, 'Soft, quick to work and quick to rot. Good for what you mean to replace.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('oak', 'Oak', 5, 1.22, 0.68, 0.85, 1.12, 1.16, 0.94, 1.12, false, 'Hard going and worth it: an oak thing takes 68% of the knocks and holds 12% more.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('maple', 'Maple', 1, 1.05, 0.9, 1, 1.05, 1.02, 1, 1.05, false, 'Even-tempered. Nothing it is best at and nothing it is bad at.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('willow', 'Willow', -3, 0.78, 1.12, 1.12, 0.94, 0.9, 1.08, 0.95, false, 'Springy and very light. The bowyer''s wood for a short bow.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('cedar', 'Cedar', 4, 0.9, 0.86, 0.35, 1, 1, 0.98, 1, false, 'Barely rots at all. Whatever you leave out in the rain, make it of this.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('apple', 'Apple', 3, 1.18, 0.74, 0.95, 1.08, 1.1, 1.02, 1.06, false, 'Close, hard and heavy for a small tree. Wears like oak and takes a finer edge.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('cherry', 'Cherry', 2, 1.02, 0.82, 0.9, 1.06, 1.06, 1.1, 1.04, false, 'Fine in the grain and stable with it. The best wood on the island for a tool handle.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('olive', 'Olive', 6, 1.3, 0.6, 0.55, 1.14, 1.2, 0.9, 1.08, false, 'Wild grained, oily and nearly unsplittable. Murder to work and it outlasts everything.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('pear', 'Pear', 3, 1.16, 0.76, 0.95, 1.06, 1.08, 1.06, 1.05, false, 'Close and pink-brown, and it carves cleaner than apple. The turner''s wood.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('plum', 'Plum', 3, 1.12, 0.78, 0.9, 1.08, 1.06, 1.02, 1.04, false, 'Hard and streaked with red. Handsome in a handle, and it holds a polish.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('peach', 'Peach', 1, 1, 0.94, 1.05, 1.02, 1, 1.02, 1, false, 'Soft for an orchard wood and quick to rot. Good for what you mean to replace.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('fig', 'Fig', 0, 0.86, 1.05, 1.15, 0.96, 0.94, 1, 0.98, false, 'Light, spongy and not much good for anything but the fruit. Plant it for that.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('lemon', 'Lemon', 2, 1.06, 0.86, 0.85, 1.04, 1.04, 1.04, 1.02, false, 'Pale, even and faintly scented on the saw. A fine wood for small work.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('pomegranate', 'Pomegranate', 4, 1.2, 0.72, 0.8, 1.1, 1.1, 0.98, 1.06, false, 'Dense and twisted, off a small tree. Stubborn to work and very hard-wearing.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('apricot', 'Apricot', 2, 1.08, 0.84, 0.9, 1.06, 1.04, 1.04, 1.02, false, 'Hard and golden, close to plum. Little of it, and worth keeping for a handle.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('quince', 'Quince', 3, 1.14, 0.78, 0.92, 1.06, 1.06, 1.02, 1.04, false, 'Close-grained like pear and a shade harder. It takes a fine edge.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('copper', 'Copper', 0, 1, 1, 1, 0.85, 0.9, 0.9, 1, false, 'The metal everything starts in. Soft, plentiful, forgiving.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('iron', 'Iron', 2, 1.1, 0.75, 1.35, 1.12, 1.12, 1.1, 1, false, 'What the island is really built on. Harder than copper at everything, and it rusts if you leave it out.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('tin', 'Tin', -2, 0.85, 1.5, 1.1, 0.5, 0.55, 0.6, 1, false, 'Too soft to be anything but stock for an alloy.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('zinc', 'Zinc', -1, 0.9, 1.4, 1.05, 0.55, 0.6, 0.65, 1, false, 'Brittle. It goes into brass and not into anything you swing.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('lead', 'Lead', -3, 1.95, 1.6, 0.7, 0.45, 0.72, 0.5, 1, false, 'Heavy and soft. A lead tool bends the first time you lean on it.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('silver', 'Silver', 4, 1.2, 1.2, 0.45, 0.9, 0.86, 0.86, 1, true, 'Barely tarnishes, and bites the unnatural far harder than its edge says.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('gold', 'Gold', 7, 2.1, 1.5, 0.15, 0.6, 0.75, 0.6, 1, false, 'Rots at 15% of copper''s pace and is no use for anything else. Wear it, do not fight in it.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('adamantine', 'Adamantine', 10, 0.75, 0.35, 0.15, 1.45, 1.25, 1.3, 1, false, 'Takes and holds the keenest edge on the island. A weaponsmith''s metal.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('glimmersteel', 'Glimmersteel', 12, 0.6, 0.3, 0.1, 1.3, 1.48, 1.25, 1, false, 'Light and immensely tough. What plate armour ought to be made of.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('mithril', 'Mithril', 14, 0.42, 0.25, 0.08, 1.35, 1.4, 1.38, 1, false, 'Lighter than the wood it is hafted to, and finer than anything but seryll.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('seryll', 'Seryll', 16, 0.7, 0.08, 0.02, 1.25, 1.36, 1.2, 1, false, 'Scarcely takes a mark. A seryll thing made well is a thing made once.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('bronze', 'Bronze', 1, 1.05, 0.85, 0.8, 1.06, 1.06, 1.06, 1, false, 'The first alloy worth the crucible: harder than copper in every way.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('brass', 'Brass', 1, 1.05, 0.9, 0.72, 1, 1, 1, 1, false, 'Handsome, weather-proof and middling at everything else.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('pewter', 'Pewter', -1, 1, 1.45, 0.9, 0.55, 0.6, 0.65, 1, false, 'Soft enough to shape cold. Plates and cups, nothing more.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('electrum', 'Electrum', 5, 1.5, 1.3, 0.25, 0.8, 0.86, 0.76, 1, false, 'Silver and gold together: it keeps the shine and neither one''s strength.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('steel', 'Steel', 5, 1.05, 0.5, 0.95, 1.28, 1.22, 1.24, 1, false, 'Iron with coal beaten through it. Keeps an edge twice as long and shrugs off the weather.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('diamond', 'Diamond', 12, 1, 1, 1, 1, 1, 1, 1, false, 'Clear as water and harder than anything else out of the ground. It favours mining.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('ruby', 'Ruby', 9, 1, 1, 1, 1, 1, 1, 1, false, 'Red as a coal, and as warm in the hand. It favours fighting.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('sapphire', 'Sapphire', 9, 1, 1, 1, 1, 1, 1, 1, false, 'Blue as deep water. It favours fishing.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('emerald', 'Emerald', 6, 1, 1, 1, 1, 1, 1, 1, false, 'Green as a leaf with the sun behind it. It favours forestry.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('garnet', 'Garnet', 3, 1, 1, 1, 1, 1, 1, 1, false, 'Dark red, the colour of iron in the fire. It favours blacksmithing.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('topaz', 'Topaz', 3, 1, 1, 1, 1, 1, 1, 1, false, 'Yellow as new-cut pine. It favours carpentry.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('opal', 'Opal', 9, 1, 1, 1, 1, 1, 1, 1, false, 'Every colour in it, moving as it turns. It favours taming.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('peridot', 'Peridot', 6, 1, 1, 1, 1, 1, 1, 1, false, 'Green as wheat before it turns. It favours farming.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('amethyst', 'Amethyst', 6, 1, 1, 1, 1, 1, 1, 1, false, 'The purple of a dyed robe. It favours tailoring.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('jasper', 'Jasper', 6, 1, 1, 1, 1, 1, 1, 1, false, 'Red-brown as a fired pot. It favours pottery.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('onyx', 'Onyx', 3, 1, 1, 1, 1, 1, 1, 1, false, 'Black, banded with white like a course of stone. It favours masonry.');
insert into material_def (id, name, difficulty, weight, wear, decay, edge, soak, bite, hold, bane, note) values ('amber', 'Amber', 3, 1, 1, 1, 1, 1, 1, 1, false, 'Honey gone hard, warm in the hand. It favours cooking.');
