insert into species_diet values ('rabba', 'onion');
insert into species_def values ('vola', 'Vola', 'A velvet-furred digger with a pink snout and broad shovel paws. It noses through the undergrowth for herbs and roots and would rather burrow than bite.', 16, 2, 1.9, 1, 0.12, 'a spice or vegetable', true, 'botanize', 8, 'snuffles the {food} out of your palm, then shuffles away and buries itself in the leaf litter', 'shuffles off and burrows out of sight', 4, false, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
