insert into species_diet values ('woola', 'carrot');
insert into species_diet values ('woola', 'wheat');
insert into species_diet values ('woola', 'corn');
insert into species_def values ('ulva', 'Ulva', 'Grey, lean and long in the leg, and the first thing on this island that will come at you without being struck first. Tame one and it will do the same for everything that comes near your border.', 34, 9, 2.1, 30, 0.06, 'meat', false, 'guard', 12, 'takes the {food} off your palm with its teeth and watches you back away', 'trots to the edge of the field, looks back once, and is gone', 4, false, false, false, false, false, false, false, true, false, false, true, false, null, null, 'aggressive', null, 'cut', null, null);
insert into species_diet values ('ulva', 'meat');
insert into species_diet values ('ulva', 'cooked_meat');
insert into species_def values ('magga', 'Magga', 'A sharp-eyed black and white bird that lives in the treetops and cannot leave anything shiny where it lies. Tamed, it clears a settlement of everything dropped and forgotten; wild, it is the reason your things are not where you left them.', 16, 3, 2, 5, 0.14, 'a berry or a handful of nuts', true, 'fetch', 12, 'snatches the {food} and is twenty feet up a tree before you can blink', 'lifts off with a rattle of wings and is gone over the trees', 4, false, true, false, false, false, false, false, false, false, false, false, false, null, null, null, null, 'cut', null, null);
insert into species_diet values ('magga', 'blueberry');
