insert into species_diet values ('magga', 'nuts');
insert into species_def values ('mola', 'Mola', 'A heavy-shouldered mole with claws like trowels and grit worked into its coat. It can smell metal through a foot of stone and would rather be underground than not.', 22, 4, 1.5, 1, 0.1, 'a spice', true, 'mine', 8, 'noses the {food} over, thinks better of you, and digs itself out of sight', 'digs straight down and is gone', 4, false, false, true, false, false, false, false, false, false, false, false, false, null, null, null, null, 'cut', null, null);
insert into species_diet values ('mola', 'sage');
insert into species_diet values ('mola', 'basil');
