insert into species_diet values ('mola', 'mint');
insert into species_diet values ('mola', 'rosemary');
insert into species_def values ('seavic', 'Seavic', 'A quick red-brown squirrel with a tail it wears like a cloak and cheeks it stuffs with seed. It lives in the treetops and cannot leave a field alone.', 14, 2, 2.6, 1, 0.12, 'an acorn or a handful of nuts', true, 'farm', 8, 'stuffs the {food} into its cheeks and is up the nearest trunk before you can blink', 'flicks its tail and runs up the nearest tree', 4, false, true, false, false, false, false, false, false, false, false, false, false, null, null, 'passive', null, null, null, null);
insert into species_diet values ('seavic', 'acorn');
insert into species_diet values ('seavic', 'nuts');
insert into species_def values ('roxxen', 'Roxxen', 'A great slab-shouldered ox with horns that sweep forward and a head it holds low. It will not start anything, and it will finish most things that start with it. Nothing but a Shaggan pulls a loaded wagon like a pair of them.', 80, 11, 1.1, 25, 0.07, 'grass or grain', false, null, 6, 'chews through the {food} without once looking up, and goes back to the grass', 'walks off at its own pace and does not look back', 4, false, false, false, false, false, false, false, false, false, false, true, false, null, null, null, null, 'crush', null, null);
insert into species_diet values ('roxxen', 'mixed_grass');
insert into species_diet values ('roxxen', 'wheat');
insert into species_diet values ('roxxen', 'corn');
insert into species_diet values ('roxxen', 'cabbage');
insert into species_diet values ('roxxen', 'carrot');
insert into species_def values ('orse', 'Orse', 'Long in the leg and deep in the chest, with a mane that falls to one side. It will carry a rider once it is saddled and bridled, and the further it has been worked the surer its footing on a bad slope.', 50, 7, 3, 30, 0.07, 'grass, grain or a root', false, null, 6, 'lips the {food} out of your hand, tosses its head, and moves off a few lengths', 'wheels away at a canter and is over the rise before you can call it', 4, false, false, false, false, false, false, false, false, false, false, true, false, null, null, null, null, 'crush', null, null);
insert into species_diet values ('orse', 'mixed_grass');
insert into species_diet values ('orse', 'wheat');
insert into species_diet values ('orse', 'corn');
insert into species_diet values ('orse', 'carrot');
insert into species_diet values ('orse', 'acorn');
insert into species_def values ('rowl', 'Rowl', 'A deep-chested hunter that runs the treeline in the half-light. It hunts the moment it sees you, and tamed it will hunt for you instead: give it a settlement and it works a circuit of it, and the more it fights the wider that circuit gets.', 46, 14, 2.5, 35, 0.05, 'meat', false, 'hunt', 12, 'takes the {food} and keeps its shoulder to you the whole while, unconvinced', 'goes off at a long easy lope and is lost in the trees', 4, false, true, false, false, false, false, false, true, false, false, true, false, null, 0.08, 'aggressive', null, 'cut', null, null);
insert into species_diet values ('rowl', 'meat');
insert into species_diet values ('rowl', 'cooked_meat');
insert into species_def values ('bogga', 'Bogga', 'A flat-tailed wallower, black to the shoulder and never far from the black ground. It works peat and tar out of the bog with its forepaws and thinks nothing of the smell.', 30, 4, 1.4, 10, 0.11, 'grass or a root', true, 'peat', 9, 'takes the {food} in both paws, eats it where it stands, and wallows off', 'slides back into the peat and is gone', 4, false, false, false, false, false, true, false, false, false, false, false, false, null, null, null, null, null, null, null);
insert into species_diet values ('bogga', 'mixed_grass');
insert into species_diet values ('bogga', 'cabbage');
