insert into species_def values ('sedra', 'Sedra', 'A long-necked wader that stands in the shallows all day and cuts reeds with a bill like a pair of shears. Papyrus starts with this bird whether you keep one or not.', 22, 3, 2, 8, 0.12, 'reeds or grain', true, 'reed', 10, 'lifts one foot, looks at the {food}, and goes back to the reeds', 'runs three steps on the water and is away', 4, true, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
