insert into species_def values ('holla', 'Holla', 'A barrel of a creature with a throat pouch that holds more water than you would credit. It carries the shore to your barrels so that you do not have to.', 34, 3, 1.6, 12, 0.1, 'grass or grain', true, 'water', 10, 'drinks noisily, takes the {food} as an afterthought, and lumbers off', 'wades out until only the pouch shows, and then not even that', 4, true, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
