insert into species_def values ('dowse', 'Dowse', 'A whiskered burrower that will not settle anywhere there is no metal under it. Put one on a deed and it spends its days reading the ground and telling you what is down there.', 20, 3, 1.8, 15, 0.1, 'nuts or a root', true, 'prospect', 8, 'sniffs the {food}, sniffs the ground, and decides the ground is more interesting', 'goes down a hole that was not there a moment ago', 4, false, false, true, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
