insert into species_def values ('sappa', 'Sappa', 'A moss-backed browser of the deep woods that buries more seed than it eats and forgets where. Kept on a deed it plants the ground back up behind your axe.', 26, 3, 1.7, 10, 0.12, 'nuts or an acorn', true, 'plant', 10, 'buries the {food} instead of eating it and wanders off pleased with itself', 'goes up the nearest trunk and out of sight among the leaves', 4, false, true, false, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
