insert into species_def values ('snedda', 'Snedda', 'A long-necked browser of the wood''s edge with a mouth like a pair of shears. It nips the dead wood out of a tree and leaves the live, and kept on a deed it prunes what would otherwise die, and nothing else.', 24, 2, 1.6, 14, 0.1, 'fruit off a tree, or a sprout', true, 'prune', 8, 'takes the {food} at the very tips of its teeth, chews it a long while, and goes back to nipping at a branch', 'reaches up into the branches and is a branch itself by the time you look again', 4, false, true, false, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
