insert into species_def values ('grubba', 'Grubba', 'A squat, hump-shouldered rooter with claws like mattock blades. It digs for what lives under old stumps and takes the stump with it; kept on a deed it clears the ground behind your axe.', 30, 4, 1.4, 8, 0.12, 'worms, or a root out of the ground', true, 'stump', 8, 'snuffles the {food} out of your hand and goes straight back to its digging', 'shoulders into the undergrowth and is gone', 4, false, true, false, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
