insert into species_def values ('plucka', 'Plucka', 'A long-armed climber of the orchard''s edge with hands like a child''s and a tail it hangs by. It goes up a bearing tree and comes down with the fruit, and kept on a deed it picks what the trees have on them and carries it home to the crate.', 18, 1, 1.7, 10, 0.12, 'fruit off a tree', true, 'fruit', 8, 'takes the {food} in both hands, eats it in three bites and is back up the tree before you have moved', 'swings up into the canopy and is gone hand over hand', 4, false, true, false, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
