insert into species_def values ('middun', 'Middun', 'A low, patient scavenger that eats what everything else has given up on. What comes out the other end is the best thing that ever happened to a field.', 24, 3, 1.5, 8, 0.13, 'meat or a vegetable', true, 'compost', 10, 'eats the {food} and everything within a foot of where it fell', 'shuffles into the undergrowth after something it can smell and you cannot', 4, false, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
