insert into species_def values ('wadd', 'Wadd', 'A slick-furred swimmer with webbed feet and a rudder of a tail. It is the one thing on the island that will take a rider across deep water instead of drowning them.', 40, 6, 2.2, 38, 0.07, 'meat or reeds', false, 'fish', 10, 'slides the {food} into the water, eats it there, and looks back at you', 'goes into the water without a sound and surfaces a long way out', 4, true, false, false, false, false, false, false, false, false, false, true, false, null, null, null, null, 'crush', null, null);
