insert into species_def values ('warda', 'Warda', 'A tall, still, long-sighted thing that picks the highest ground it can find and watches from it. Nothing comes near a settlement with one of these on the hill without you knowing.', 30, 5, 1.9, 30, 0.08, 'meat or nuts', false, null, 8, 'takes the {food} without once taking its eyes off the horizon', 'lifts, circles once to see everything, and is a speck', 4, false, false, false, false, false, false, false, false, false, false, true, false, null, null, null, null, 'cut', null, 18);
