insert into species_def values ('quill', 'Quill', 'A heavy ground-bird that would rather run than fly and would rather eat than run. Its long wing feathers grow back as fast as you can take them, which is what keeps an archer in arrows.', 26, 4, 1.9, 12, 0.11, 'grain or nuts', true, null, 6, 'bolts with the {food} and eats it at a safe distance, watching you', 'runs off with its neck out, going faster than looks possible', 4, false, false, false, false, false, false, false, false, false, false, false, false, 0.0014285714285714286, null, null, 'feather', 'pierce', null, null);
