insert into species_def values ('snout', 'Snout', 'Wrinkled, half blind, and the finest nose on the island. It smells what is under the ground, and what is under the ground on this island is other people''s lives.', 24, 4, 1.6, 50, 0.05, 'meat or nuts', false, 'seek', 10, 'works its way over the {food}, over your boots, and over the ground you are standing on', 'follows its nose away and is not seen again', 4, false, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
