insert into species_def values ('lume', 'Lume', 'A pale slow drifter that is only ever out after dark, and glows with a light that has nothing to do with fire. Keep one and it lights eight tiles round itself however dark the night.', 10, 1, 1.3, 55, 0.05, 'a gland or something sweet', true, null, 6, 'drifts around the {food} twice, dims, and drifts away', 'goes out like a blown candle and is not there when the light comes back', 4, false, false, false, false, false, false, false, false, true, false, false, false, null, null, null, null, 'burn', null, null);
