insert into class_perk values ('terraformer_quick_level', 'terraformer', 1, 10, 'Quick Level', 'Flatten takes 35% less time a go (3.5 s base).', '{"time:flatten":0.65}');
insert into class_perk values ('terraformer_bed_worker', 'terraformer', 1, 17, 'Bed Worker', 'Collect takes 30% less time a go (7 s base).', '{"time:collect":0.7}');
insert into class_perk values ('terraformer_quick_paver', 'terraformer', 1, 25, 'Quick Paver', 'Pack, Pave (cobblestone) and Pave (slabs) take 35% less time a go.', '{"time:pack":0.65,"time:pave_cobble":0.65,"time:pave_slabs":0.65}');
insert into class_perk values ('terraformer_level_hand', 'terraformer', 2, 9, 'Level Hand', 'Flatten moves two height units a go (now one).', '{"flatten:step":2}');
insert into class_perk values ('terraformer_wader', 'terraformer', 2, 14, 'Wader', 'Dig and Flatten work in water up to 20 deep (now 10).', '{"depth:dig":20}');
insert into class_perk values ('terraformer_stump_puller', 'terraformer', 2, 23, 'Stump Puller', 'Dig out the stump takes 50% less time, and gives one log of the tree''s kind (now nothing).', '{"time:dig_stump":0.5,"stump:log":1}');
insert into class_perk values ('terraformer_steep_cut', 'terraformer', 3, 12, 'Steep Cut', 'The steepest slope Dig, Drop dirt and Dredge may leave is four times your digging (now three times, and never under 40).', '{"slope:digging":4}');
insert into class_perk values ('terraformer_dredger', 'terraformer', 3, 15, 'Dredger', 'Dredge reaches bottoms up to 60 deep (now 30) and takes 20% less time a go.', '{"depth:dredge":60,"time:dredge":0.8}');
insert into class_perk values ('terraformer_bed_true', 'terraformer', 3, 26, 'Bed True', 'Pave (slabs) never fails (now a check at difficulty 10 against the slab''s QL).', '{"fail:pave_slabs":0}');
insert into class_perk values ('terraformer_frugal_cobbler', 'terraformer', 4, 27, 'Frugal Cobbler', '1 in 3 goes of Pave (cobblestone) use no stone brick.', '{"keep:pave_cobble":0.3333333333333333}');
insert into class_perk values ('terraformer_road_legs', 'terraformer', 4, 29, 'Road Legs', 'You walk 15% faster on packed dirt, cobblestone and stone slabs.', '{"walk:road":1.15}');
insert into class_perk values ('terraformer_soil_porter', 'terraformer', 4, 32, 'Soil Porter', 'Dirt, sand and clay weigh 10 kg a unit in your pack (now 20 kg).', '{"weight:dirt":0.5,"weight:sand":0.5,"weight:clay":0.5}');
insert into class_perk values ('terraformer_strong_back', 'terraformer', 5, 33, 'Strong Back', 'You carry 40 kg more before the load slows you (now 120 kg, and 5 more for every level of body strength).', '{"carry":40}');
insert into class_perk values ('terraformer_long_reach', 'terraformer', 5, 34, 'Long Reach', 'Drop dirt and Flatten take soil from carts and containers within 5 tiles (now 2.5), and what you dig goes into the nearest unlocked cart or wagon within 5 tiles that nobody else is pulling or driving (now into your pack).', '{"reach:soil":5}');
insert into class_perk values ('terraformer_dig_out_the_tile', 'terraformer', 5, 44, 'Dig Out the Tile', 'A new job, Dig out the tile: all four corners of a tile come down by one in a single go of 16 s base (four digs take 24 s), and it gives four of the material.', '{"dig_tile":1}');
insert into class_perk values ('terraformer_clean_earth', 'terraformer', 6, 5, 'Clean Earth', 'Dirt, sand, clay, peat and tar you dig, dredge, collect or flatten off come up at +10% QL.', '{"ql:dig":1.1,"ql:dredge":1.1,"ql:collect":1.1,"ql:flatten":1.1}');
insert into class_perk values ('terraformer_rare_earth', 'terraformer', 6, 6, 'Rare Earth', '1 in 100 goes of Dig, Dredge and Collect bring the material up rare, rolling on to supreme and fantastic at the odds crafting has. Nothing gathered is rare without it.', '{"rare:dig":0.01,"rare:dredge":0.01,"rare:collect":0.01}');
insert into class_perk values ('terraformer_treasure_nose', 'terraformer', 6, 20, 'Treasure Nose', 'Digging turns up a treasure map in 1 in 200 goes (now 1 in 1000).', '{"map:dig":0.005,"map:dig_tile":0.005}');
insert into class_perk values ('miner_ore_sense', 'miner', 1, 7, 'Ore Sense', 'Mine, Chip corner and Mine out the cellar work every ore at 10 less mining than it wants: copper, iron and tin at any mining, zinc at 10, lead at 20, silver at 30, gold at 40, adamantine at 50, glimmersteel at 60, mithril at 70 and seryll at 80 (now copper at 1, iron at 5, tin at 10, zinc at 20, lead at 30, silver at 40, gold at 50, adamantine at 60, glimmersteel at 70, mithril at 80 and seryll at 90).', '{"ore:below":10}');
insert into class_perk values ('miner_coal_hand', 'miner', 1, 8, 'Coal Hand', 'Mine on a coal seam brings up two coal a go (now one).', '{"count:coal":2}');
insert into class_perk values ('miner_chipper', 'miner', 1, 9, 'Chipper', 'Chip corner takes the corner down in 1 in 2 goes (now 1 in 4).', '{"chip:chance":0.5}');
insert into class_perk values ('miner_rock_slide', 'miner', 2, 13, 'Rock Slide', 'When the face drops of its own accord as you mine (1 in 30 goes), three more of what you are mining come down with it.', '{"slide:more":3}');
insert into class_perk values ('miner_wet_work', 'miner', 2, 14, 'Wet Work', 'Mine and Chip corner work in water up to 20 deep (now 10).', '{"depth:mine":20}');
insert into class_perk values ('miner_far_reader', 'miner', 2, 19, 'Far Reader', 'Prospect reads three tiles further (now three, and one more for every 10 prospecting).', '{"further:prospect":3}');
insert into class_perk values ('miner_quick_pick', 'miner', 3, 1, 'Quick Pick', 'Mine takes 25% less time a go (8 s base).', '{"time:mine":0.75}');
insert into class_perk values ('miner_rich_seam', 'miner', 3, 2, 'Rich Seam', '15% of goes of Mine bring up one more of what they bring up.', '{"more:mine":0.15}');
insert into class_perk values ('miner_keen_trowel', 'miner', 3, 25, 'Keen Trowel', 'Investigate finds something 15 percentage points more often, up to 85% (now 14%, plus 40% of your archaeology and 10% of the trowel''s QL, at most 70%).', '{"find:investigate":0.15,"cap:investigate":0.85}');
insert into class_perk values ('miner_sure_swing', 'miner', 4, 3, 'Sure Swing', 'Mine fails half as often (now a check at difficulty 12, with the pickaxe''s QL).', '{"fail:mine":0.5}');
insert into class_perk values ('miner_pieces_that_fit', 'miner', 4, 27, 'Pieces that Fit', 'While you hold pieces of a relic that is not yet whole, half of the relic pieces Investigate turns up are a piece you are missing of one of those.', '{"fit:relic":0.5}');
insert into class_perk values ('miner_ore_cart', 'miner', 4, 35, 'Ore Cart', 'What Mine brings up goes into the nearest unlocked cart or wagon that nobody else is pulling or driving, or container you built or that stands on your settlement, within 5 tiles (now into your pack).', '{"into:mine":5}');
insert into class_perk values ('miner_face_shaper', 'miner', 5, 11, 'Face Shaper', 'When Chip corner takes the corner down, it drops two steps (now one), but never past a level you have taken.', '{"chip:step":2}');
insert into class_perk values ('miner_gem_eye', 'miner', 5, 15, 'Gem Eye', 'Mine turns up a gem in 1 in 150 goes (now 1 in 400).', '{"gem:mine":0.006666666666666667}');
insert into class_perk values ('miner_bauble_hunter', 'miner', 5, 28, 'Bauble Hunter', '40% of what Investigate finds is a tarnished bauble (now 30%).', '{"share:bauble":0.4}');
insert into class_perk values ('miner_rare_ore', 'miner', 6, 6, 'Rare Ore', '1 in 100 goes of Mine bring what they bring up rare, rolling on to supreme and fantastic at the odds crafting has. Nothing mined is rare without it.', '{"rare:mine":0.01}');
insert into class_perk values ('miner_treasure_in_the_rock', 'miner', 6, 17, 'Treasure in the Rock', 'Mine turns up a treasure map in 1 in 200 goes (now 1 in 1000).', '{"map:mine":0.005}');
insert into class_perk values ('miner_pan', 'miner', 6, 50, 'Pan', 'A new job, Pan, on sand with water at one of its corners: 1 in 8 goes give copper ore, tin ore, silver ore or gold ore, each as likely, at a QL set by your prospecting.', '{"pan":0.125}');
insert into class_perk values ('mason_quick_chisel', 'mason', 1, 1, 'Quick Chisel', 'Stonecutting takes 25% less time a go: bricks, whetstones, querns and slabs (now 6–16 s base).', '{"time:make_stone_brick":0.75,"time:make_slate_brick":0.75,"time:make_marble_brick":0.75,"time:make_sandstone_brick":0.75,"time:make_whetstone":0.75,"time:make_quern":0.75,"time:make_stone_slab":0.75,"time:make_slate_slab":0.75,"time:make_marble_slab":0.75,"time:make_sandstone_slab":0.75}');
insert into class_perk values ('mason_quick_mason', 'mason', 1, 8, 'Quick Mason', 'Build wall and Build floor take 30% less time a go on stone, anything but log, plank or timbercraft (5 s base).', '{"time:build_stone":0.7}');
insert into class_perk values ('mason_concrete_hand', 'mason', 1, 17, 'Concrete Hand', 'Raise the rock with concrete never fails (now a check at difficulty 10, and the concrete is lost when it does).', '{"fail:raise_rock":0}');
insert into class_perk values ('mason_sure_chisel', 'mason', 2, 4, 'Sure Chisel', 'Stonecutting fails half as often (now a check at difficulty 10–24).', '{"fail:make_stone_brick":0.5,"fail:make_slate_brick":0.5,"fail:make_marble_brick":0.5,"fail:make_sandstone_brick":0.5,"fail:make_whetstone":0.5,"fail:make_quern":0.5,"fail:make_stone_slab":0.5,"fail:make_slate_slab":0.5,"fail:make_marble_slab":0.5,"fail:make_sandstone_slab":0.5}');
insert into class_perk values ('mason_double_lift', 'mason', 2, 18, 'Double Lift', 'Raise the rock with concrete lifts the corner two steps for one concrete (now one), where the slope you may leave and your level allow it; where they do not, one.', '{"lift:raise_rock":2}');
insert into class_perk values ('mason_steep_stone', 'mason', 2, 19, 'Steep Stone', 'The steepest slope raising rock may leave is four times your masonry (now three times, and never under 40).', '{"slope:masonry":4}');
insert into class_perk values ('mason_good_mix', 'mason', 3, 20, 'Good Mix', 'Mix concrete makes two concrete out of the same mortar and ashes (now one).', '{"count:concrete":2}');
insert into class_perk values ('mason_wet_set', 'mason', 3, 22, 'Wet Set', 'Raising rock works on rock under water up to 10 deep (now only above the water).', '{"depth:raise_rock":10}');
insert into class_perk values ('mason_brick_porter', 'mason', 3, 33, 'Brick Porter', 'Bricks and slabs of stone, slate, marble or sandstone weigh half as much in your pack: a brick 7.5 kg and a slab 9 kg (now 15 and 18).', '{"weight:stone_brick":0.5,"weight:slate_brick":0.5,"weight:marble_brick":0.5,"weight:sandstone_brick":0.5,"weight:stone_slab":0.5,"weight:slate_slab":0.5,"weight:marble_slab":0.5,"weight:sandstone_slab":0.5}');
insert into class_perk values ('mason_three_from_a_shard', 'mason', 4, 2, 'Three from a Shard', 'Chiselling a brick of stone, slate, marble or sandstone makes three at a go (now two).', '{"count:stone_brick":3,"count:slate_brick":3,"count:marble_brick":3,"count:sandstone_brick":3}');
insert into class_perk values ('mason_two_at_a_time', 'mason', 4, 9, 'Two at a Time', 'Build wall and Build floor lay two units a go on stone, anything but log, plank or timbercraft, when you have them (now one; a stone-brick wall is 24 stone bricks and 12 mortar).', '{"lay:build_stone":2}');
insert into class_perk values ('mason_bridge_mason', 'mason', 4, 29, 'Bridge Mason', 'Work on a stone arch takes 30% less time a go (9 s base), and one spans 10 tiles (now 8).', '{"time:bridge_stone":0.7,"span:bridge_stone":10}');
insert into class_perk values ('mason_salvage', 'mason', 5, 16, 'Salvage', 'Remove wall gives back half the stone laid in a wall of stone, anything but log, plank or timbercraft, rounded down: 12 of a stone-brick wall''s 24 stone bricks (now none).', '{"salvage:build_stone":0.5}');
insert into class_perk values ('mason_hod_carrier', 'mason', 5, 35, 'Hod Carrier', 'Build wall and Build floor on stone, anything but log, plank or timbercraft, also take from crates, carts and containers within 5 tiles that a craft may take from (now only your pack and a crate on the tile).', '{"reach:build_stone":5}');
insert into class_perk values ('mason_rubble_fill', 'mason', 5, 48, 'Rubble Fill', 'A new job, Raise the rock with rubble: a corner of bare rock rises a step for five rock shards instead of a concrete, under the same rules as concrete and the same check at difficulty 10.', '{"rubble":5}');
insert into class_perk values ('mason_tall_walls', 'mason', 6, 12, 'Tall Walls', 'Every stone in a building you planned stands two storeys taller, up to 12 (now marble, stone brick, ornate silver, ornate gold and stained glass 10, slate 8, sandstone and clay bricks 7, cobblestone 6, clay adobe 5, and 10 at most). Timber stands no taller, and a building stops at the shortest thing in it. Every storey past the tenth takes masonry 100 in the storey below.', '{"storeys:build_stone":2}');
insert into class_perk values ('mason_nothing_wasted', 'mason', 6, 24, 'Nothing Wasted', 'A failed smelter or kiln keeps its materials (now they are lost).', '{"spare:make_smelter":1,"spare:make_kiln":1}');
insert into class_perk values ('mason_repoint', 'mason', 6, 47, 'Repoint', 'A new job, Repoint, on a finished wall of stone, anything but log, plank or timbercraft: it is laid again in another stone in one go of 30 s base. You pay the new stone''s whole bill and get half the old stone back, rounded down.', '{"repoint":1}');
insert into class_perk values ('carpenter_quick_saw', 'carpenter', 1, 1, 'Quick Saw', 'Saw into planks, Saw into timbers and Carve shafts take 30% less time a go (5 s base).', '{"time:make_planks":0.7,"time:make_timbers":0.7,"time:make_shafts":0.7}');
insert into class_perk values ('carpenter_string_maker', 'carpenter', 1, 37, 'String Maker', 'Twist a bowstring takes 1 yarn (now 2) and never fails (now a check at difficulty 14).', '{"need:make_bow_string":0.5,"fail:make_bow_string":0}');
insert into class_perk values ('carpenter_saw_care', 'carpenter', 1, 45, 'Saw Care', 'Saws, carving knives, mallets and files take half the damage a use, at any quality and of any wood or metal: a go of work at the bench wears the tool it is done with.', '{"wear:saw":0.5,"wear:carving_knife":0.5,"wear:mallet":0.5,"wear:file":0.5}');
insert into class_perk values ('carpenter_heavy_timber', 'carpenter', 2, 3, 'Heavy Timber', 'Saw into timbers makes three timbers from a log (now two).', '{"count:timber":3}');
insert into class_perk values ('carpenter_thatcher', 'carpenter', 2, 6, 'Thatcher', 'Bundle into thatch makes two thatch from two mixed grass (now one).', '{"count:thatch":2}');
insert into class_perk values ('carpenter_shipwright', 'carpenter', 2, 14, 'Shipwright', 'Building a rowing boat, a sailing boat or a caravel takes 30% less time (34 s, 70 s and 180 s base).', '{"time:make_rowing_boat":0.7,"time:make_sailing_boat":0.7,"time:make_caravel":0.7}');
insert into class_perk values ('carpenter_keel_layer', 'carpenter', 3, 15, 'Keel Layer', 'Boats you build go 10% faster on the water, whoever is working them: a rowing boat 2.1, a sailing boat 3.7 and a caravel 4.4 tiles a second at a fair effort (now 1.9, 3.4 and 4). It stays with the boat whoever has it after.', '{"speed:rowing_boat":1.1,"speed:sailing_boat":1.1,"speed:caravel":1.1}');
insert into class_perk values ('carpenter_timber_salvage', 'carpenter', 3, 26, 'Timber Salvage', 'Remove wall gives back half the logs or planks laid in a wall of log, plank or timbercraft, rounded down: 12 of a plank wall''s 24 planks (now none).', '{"salvage:build_wood":0.5}');
insert into class_perk values ('carpenter_bowyers_draw', 'carpenter', 3, 31, 'Bowyer''s Draw', 'Bows you make hit 10% harder: a short bow 8.8, a medium bow 12.1, a long bow 16.5 and a composite bow 23.1 base damage (now 8, 11, 15 and 21). It stays with the bow whoever has it after.', '{"damage:short_bow":1.1,"damage:medium_bow":1.1,"damage:long_bow":1.1,"damage:composite_bow":1.1}');
insert into class_perk values ('carpenter_deep_hold', 'carpenter', 4, 16, 'Deep Hold', 'Boats you build carry 25% more, before the wood and the rarity: a rowing boat 375, a sailing boat 1875 and a caravel 6250 (now 300, 1500 and 5000). It stays with the boat whoever has it after.', '{"hold:rowing_boat":1.25,"hold:sailing_boat":1.25,"hold:caravel":1.25}');
insert into class_perk values ('carpenter_sure_hull', 'carpenter', 4, 19, 'Sure Hull', 'Building a boat, a cart or a wagon fails half as often (now a check at difficulty 18–60).', '{"fail:make_cart":0.5,"fail:make_large_cart":0.5,"fail:make_wagon":0.5,"fail:make_rowing_boat":0.5,"fail:make_sailing_boat":0.5,"fail:make_caravel":0.5}');
insert into class_perk values ('carpenter_true_bow', 'carpenter', 4, 32, 'True Bow', 'Bows you make reach 10% further: a short bow 6.6, a medium bow 9.9, a long bow 14.3 and a composite bow 18.7 tiles (now 6, 9, 13 and 17). It stays with the bow whoever has it after.', '{"range:short_bow":1.1,"range:medium_bow":1.1,"range:long_bow":1.1,"range:composite_bow":1.1}');
insert into class_perk values ('carpenter_clean_sawing', 'carpenter', 5, 2, 'Clean Sawing', 'Saw into planks makes four planks from a log (now three).', '{"count:plank":4}');
insert into class_perk values ('carpenter_smooth_axle', 'carpenter', 5, 18, 'Smooth Axle', 'Large carts and wagons you build go 10% faster behind their team, up to 4.4 tiles a second (now at most 4). It stays with the vehicle whoever has it after.', '{"speed:large_cart":1.1,"speed:wagon":1.1}');
insert into class_perk values ('carpenter_fence_builder', 'carpenter', 5, 25, 'Fence Builder', 'Fences, fence gates, iron-bound gates and half walls take half the time a go (5 s base) and half the material, rounded up: a plank fence 4 planks and 1 timber (now 8 planks and 2 timbers). Hinges and brackets are as they were.', '{"time:fence":0.5,"bill:fence":0.5}');
insert into class_perk values ('carpenter_master_joiner', 'carpenter', 6, 10, 'Master Joiner', 'Furniture you make with carpentry or fine carpentry, all 45 pieces of it with the boats, carts and wagons, comes out rare 1 in 50 (now 1 in 100); supreme and fantastic follow at their usual odds.', '{"rare:make_stool":0.02,"rare:make_chair":0.02,"rare:make_bench":0.02,"rare:make_table":0.02,"rare:make_long_table":0.02,"rare:make_desk":0.02,"rare:make_bed":0.02,"rare:make_cot":0.02,"rare:make_chest":0.02,"rare:make_coffer":0.02,"rare:make_cupboard":0.02,"rare:make_wardrobe":0.02,"rare:make_shelves":0.02,"rare:make_bookshelf":0.02,"rare:make_larder":0.02,"rare:make_barrel":0.02,"rare:make_stall":0.02,"rare:make_mailbox":0.02,"rare:make_creature_crate":0.02,"rare:make_lectern":0.02,"rare:make_coat_rack":0.02,"rare:make_planter":0.02,"rare:make_firewood_rack":0.02,"rare:make_crate_shelf":0.02,"rare:make_bell":0.02,"rare:make_hive":0.02,"rare:make_spindle":0.02,"rare:make_loom":0.02,"rare:make_lamp_post":0.02,"rare:make_rose_arch":0.02,"rare:make_bulk_bin":0.02,"rare:make_craft_bin":0.02,"rare:make_seed_bin":0.02,"rare:make_sprout_bin":0.02,"rare:make_trash_crate":0.02,"rare:make_cart":0.02,"rare:make_large_cart":0.02,"rare:make_wagon":0.02,"rare:make_rowing_boat":0.02,"rare:make_sailing_boat":0.02,"rare:make_caravel":0.02,"rare:make_small_barrel":0.02,"rare:make_large_barrel":0.02,"rare:make_sign":0.02,"rare:make_great_sign":0.02}');
insert into class_perk values ('carpenter_deep_drawers', 'carpenter', 6, 12, 'Deep Drawers', 'Chests, coffers, cupboards, wardrobes, shelves, bookshelves, larders, small barrels, barrels, large barrels, raw material bins, craft material bins, seed bins and sprout bins you make hold 20% more, before the wood and the rarity: a chest 72 (now 60) and a barrel 96 litres (now 80). It stays with the piece whoever has it after.', '{"hold:chest":1.2,"hold:coffer":1.2,"hold:cupboard":1.2,"hold:wardrobe":1.2,"hold:shelves":1.2,"hold:bookshelf":1.2,"hold:larder":1.2,"hold:small_barrel":1.2,"hold:barrel":1.2,"hold:large_barrel":1.2,"hold:bulk_bin":1.2,"hold:craft_bin":1.2,"hold:seed_bin":1.2,"hold:sprout_bin":1.2}');
insert into class_perk values ('carpenter_bridge_wright', 'carpenter', 6, 27, 'Bridge Wright', 'Work on a wooden bridge or a rope bridge takes 30% less time a go (9 s base), and they span 2 tiles more: 12 and 16 (now 10 and 14).', '{"time:bridge_wood":0.7,"time:bridge_rope":0.7,"span:bridge_wood":12,"span:bridge_rope":16}');
insert into class_perk values ('smith_glassblower', 'smith', 1, 8, 'Glassblower', 'Melt into glass makes three glass lumps from three sand (now two).', '{"count:glass_lump":3}');
insert into class_perk values ('smith_mail_maker', 'smith', 1, 26, 'Mail Maker', 'Chain you beat out turns aside 10% more of a blow, up to the 92% no piece passes: chain coif, chain hauberk, chain sleeves, chain leggings and chain boots. Chain that turns aside 46% turns 50.6%. It stays with the piece whoever wears it after.', '{"soak:chain_coif":1.1,"soak:chain_hauberk":1.1,"soak:chain_sleeves":1.1,"soak:chain_leggings":1.1,"soak:chain_boots":1.1}');
insert into class_perk values ('smith_plate_maker', 'smith', 1, 27, 'Plate Maker', 'Plate you beat out turns aside 10% more of a blow, up to the 92% no piece passes: helm, breastplate, plate arms, plate legs and plate boots. Plate that turns aside 62% turns 68.2%. It stays with the piece whoever wears it after.', '{"soak:helm":1.1,"soak:plate_breastplate":1.1,"soak:plate_arms":1.1,"soak:plate_legs":1.1,"soak:plate_boots":1.1}');
insert into class_perk values ('smith_toolsmith', 'smith', 2, 30, 'Toolsmith', 'Tool heads and blades you beat out come out at +10% QL: rake heads, shovel heads, hatchet heads, sickle blades, pickaxe heads, hammer heads, knife blades, saw blades and trowel blades. One that would come out at 50 comes out at 55.', '{"ql:rake_head":1.1,"ql:shovel_head":1.1,"ql:hatchet_head":1.1,"ql:sickle_blade":1.1,"ql:pickaxe_head":1.1,"ql:hammer_head":1.1,"ql:knife_blade":1.1,"ql:saw_blade":1.1,"ql:trowel_blade":1.1}');
insert into class_perk values ('smith_metal_polisher', 'smith', 2, 32, 'Metal Polisher', 'Improve raises anything of metal 50% more a pass: at 50 in the skill, a QL 40 piece gains 3.3 a pass (now 2.2).', '{"improve:metal":1.5}');
insert into class_perk values ('smith_ingots', 'smith', 2, 49, 'Ingots', 'Pour 5 lumps of a metal into an ingot at the smelter, at the lumps'' QL. An ingot weighs half what its lumps do and counts as 5 lumps wherever the smelter, the anvil, a recipe or Improve takes lumps; what a job does not use of one comes back as lumps.', '{"ingot":1}');
insert into class_perk values ('smith_hard_sand', 'smith', 3, 12, 'Hard Sand', 'Moulds you make last twice as many fillings: a QL 50 mould 14 fillings of copper (now 7). Every mould but the anvil''s, which the one filling uses up. It stays with the mould whoever has it after.', '{"last:pan_mould":2,"last:rake_head_mould":2,"last:shovel_head_mould":2,"last:hatchet_head_mould":2,"last:sickle_blade_mould":2,"last:pickaxe_head_mould":2,"last:hammer_head_mould":2,"last:knife_blade_mould":2,"last:sword_blade_mould":2,"last:helm_mould":2,"last:nail_mould":2,"last:ribbon_mould":2,"last:axle_mould":2,"last:arrow_head_mould":2,"last:short_sword_blade_mould":2,"last:long_sword_blade_mould":2,"last:axe_head_mould":2,"last:maul_head_mould":2,"last:spear_head_mould":2,"last:shield_boss_mould":2,"last:file_mould":2,"last:chisel_mould":2,"last:saw_blade_mould":2,"last:trowel_blade_mould":2,"last:coin_die_mould":2,"last:horseshoe_mould":2,"last:hinge_mould":2,"last:bracket_mould":2,"last:ring_mould":2,"last:pendant_mould":2,"last:bell_mould":2,"last:statue_mould":2,"last:chain_coif_mould":2,"last:chain_hauberk_mould":2,"last:chain_sleeves_mould":2,"last:chain_leggings_mould":2,"last:chain_boots_mould":2,"last:plate_breastplate_mould":2,"last:plate_arms_mould":2,"last:plate_legs_mould":2,"last:plate_boots_mould":2}');
insert into class_perk values ('smith_second_heat', 'smith', 3, 20, 'Second Heat', 'A go of Smith that fails leaves its casting where it was, to be beaten again (now the metal is lost).', '{"spare:smith":1}');
insert into class_perk values ('smith_nail_maker', 'smith', 3, 22, 'Nail Maker', 'A filling of the nail mould beats out eight nails at the anvil (now five): 8 nails to a lump of iron, and to 10 of gold.', '{"count:nail":8}');
insert into class_perk values ('smith_keen_edge', 'smith', 4, 24, 'Keen Edge', 'Weapons fitted from heads and blades you beat out hit 10% harder, whoever fits them: hatchets, butchering knives, swords, short swords, long swords, battle axes, mauls, spears, hunting knives, carving knives, javelins and throwing axes. A sword 11 base damage (now 10). It goes from the part into the weapon, and stays with it whoever has it after.', '{"damage:hatchet_head":1.1,"damage:knife_blade":1.1,"damage:sword_blade":1.1,"damage:arrow_head":1.1,"damage:short_sword_blade":1.1,"damage:long_sword_blade":1.1,"damage:axe_head":1.1,"damage:maul_head":1.1,"damage:spear_head":1.1}');
insert into class_perk values ('smith_balanced', 'smith', 4, 25, 'Balanced', 'Weapons fitted from heads and blades you beat out land 5% more often, whoever fits them, up to the 96% no swing passes: a 70% swing lands 73.5%. It goes from the part into the weapon, and stays with it whoever has it after.', '{"aim:hatchet_head":1.05,"aim:knife_blade":1.05,"aim:sword_blade":1.05,"aim:arrow_head":1.05,"aim:short_sword_blade":1.05,"aim:long_sword_blade":1.05,"aim:axe_head":1.05,"aim:maul_head":1.05,"aim:spear_head":1.05}');
insert into class_perk values ('smith_forge_reach', 'smith', 4, 36, 'Forge Reach', 'Work at a smelter or an anvil takes what it uses from your stores within 6 tiles (now 3): smelt, melt down, cast an anvil, pour a mould, pour ingots, fuel, smith and strike coins, and every recipe made at the smelter.', '{"reach:forge":6}');
insert into class_perk values ('smith_sure_alloy', 'smith', 5, 7, 'Sure Alloy', 'Mix bronze, Make steel, Mix brass, Mix pewter and Mix electrum fail half as often (now a check at difficulty 10–20).', '{"fail:make_bronze":0.5,"fail:make_steel":0.5,"fail:make_brass":0.5,"fail:make_pewter":0.5,"fail:make_electrum":0.5}');
insert into class_perk values ('smith_reclaimer', 'smith', 5, 9, 'Reclaimer', 'Melt down gives back 75% of the lumps a thing holds, at 85% of its QL less its damage (now 50%, at 70%): a chain hauberk 4 lumps (now 3).', '{"melt:share":0.75,"melt:keep":0.85}');
insert into class_perk values ('smith_clean_pour', 'smith', 5, 13, 'Clean Pour', 'A mould''s damage no longer counts against what you pour from it: a QL 50 mould at 40 damage pours as 50 (now 30), which the casting takes together with the lump''s QL and your smelting''s.', '{"pour:wear":0}');
insert into class_perk values ('smith_sure_hammer', 'smith', 6, 16, 'Sure Hammer', 'Smith and strike coins at the anvil fail half as often (now a check at difficulty 6–32 for a piece and 12 for coins, and more for a hard metal).', '{"fail:smith":0.5,"fail:strike_coins":0.5}');
insert into class_perk values ('smith_long_shift', 'smith', 6, 38, 'Long Shift', 'You can keep two more jobs queued: 5 at 20 mind logic (now 3), and one more for every 10 above that, as before.', '{"jobs":2}');
insert into class_perk values ('smith_temper_bath', 'smith', 6, 45, 'Temper Bath', 'A weapon or tool you finish can be quenched once, for +5 QL, by you or any Smith with Temper Bath: Quench it standing at water, or beside a barrel or a well of it. That is rakes, shovels, hatchets, sickles, hammers, pickaxes, butchering knives, swords, short swords, long swords, battle axes, mauls, spears, hunting knives, carving knives, saws, trowels, javelins, throwing axes, frying pans, files, stone chisels and coin dies: what is fitted from a head or blade the anvil beat out, and what the anvil beats out whole. It stays with the thing until it is quenched.', '{"temper:rake":5,"temper:shovel":5,"temper:hatchet":5,"temper:sickle":5,"temper:hammer":5,"temper:pickaxe":5,"temper:butchering_knife":5,"temper:sword":5,"temper:short_sword":5,"temper:long_sword":5,"temper:battle_axe":5,"temper:maul":5,"temper:spear":5,"temper:hunting_knife":5,"temper:carving_knife":5,"temper:saw":5,"temper:trowel":5,"temper:javelin":5,"temper:throwing_axe":5,"temper:frying_pan":5,"temper:file":5,"temper:chisel":5,"temper:coin_die":5}');
insert into class_perk values ('forester_woodsmans_stride', 'forester', 1, 34, 'Woodsman''s Stride', 'You walk through bush, reed, stump and marsh at full pace, on foot (now bush at 50%, reed at 80%, stump at 70% and marsh at 60% of it).', '{"walk:bush":2,"walk:reed":1.25,"walk:stump":1.4285714285714286,"walk:marsh":1.6666666666666667}');
insert into class_perk values ('forester_tap_resin', 'forester', 1, 43, 'Tap Resin', 'Tap resin (a job with a carving knife, 6 s): one tar from a living pine, once a day for each; the day turns at 13 o''clock UTC, when the trees grow.', '{"tap_resin":1}');
insert into class_perk values ('forester_clear_brush', 'forester', 1, 44, 'Clear Brush', 'Clear brush (a job with a sickle, 16 s): every bush and reed in the 3×3 tiles around the one you choose, cleared in one go. A bush leaves grass and reeds dirt; it gives nothing.', '{"clear_brush":1}');
insert into class_perk values ('forester_nest_finder', 'forester', 2, 21, 'Nest Finder', '1 in 10 trees you fell for timber give three feathers, at the logs'' QL.', '{"nest:chance":0.1,"nest:feathers":3}');
insert into class_perk values ('forester_honey_hunter', 'forester', 2, 22, 'Honey Hunter', '1 in 20 trees you fell for timber give two honey, at the logs'' QL.', '{"honey:chance":0.05,"honey:count":2}');
insert into class_perk values ('forester_coppice', 'forester', 2, 40, 'Coppice', 'Coppice (a job with a hatchet, 8 s, a check at difficulty 10): a mature, old or very old tree is cut back to young for two logs, and stays standing to grow on.', '{"coppice":2}');
insert into class_perk values ('forester_clean_stroke', 'forester', 3, 1, 'Clean Stroke', 'Each stroke of Cut down takes 25% less time (8 s base), on a tree or a bush.', '{"time:cut_down":0.75}');
insert into class_perk values ('forester_heavy_swing', 'forester', 3, 2, 'Heavy Swing', 'Trees come down in one stroke fewer, and never under one: young 1 (now 2), mature 2 (now 3), old 2 (now 3), very old 3 (now 4) and shrivelled 1 (now 2).', '{"fewer:cut_down":1}');
insert into class_perk values ('forester_sure_hatchet', 'forester', 3, 3, 'Sure Hatchet', 'Cut down glances off half as often (now a check at difficulty 10), on a tree or a bush.', '{"fail:cut_down":0.5}');
insert into class_perk values ('forester_clean_drop', 'forester', 4, 7, 'Clean Drop', 'A tree you fell leaves grass where it stood (now a stump, for a day or until it is dug out).', '{"stump:clear":1}');
insert into class_perk values ('forester_fruitful', 'forester', 4, 16, 'Fruitful', 'Every pick of Pick fruit gives one more fruit.', '{"more:pick_fruit":1}');
insert into class_perk values ('forester_kindling', 'forester', 4, 24, 'Kindling', 'Cutting down a bush gives two shafts (now nothing).', '{"bush:shaft":2}');
insert into class_perk values ('forester_sprout_picker', 'forester', 5, 10, 'Sprout Picker', 'Pick sprout never fails (now a check at difficulty 15) and gives two sprouts (now one).', '{"fail:pick_sprout":0,"count:sprout":2}');
insert into class_perk values ('forester_nursery', 'forester', 5, 11, 'Nursery', 'A sprout you plant comes up a mature tree (now young): it fells for four logs (now two), and a fruit tree bears at once.', '{"grown:plant":1}');
insert into class_perk values ('forester_hedge_harvest', 'forester', 5, 20, 'Hedge Harvest', 'Every go of harvesting a bush gives one more of what it bears (rose petals or lavender).', '{"more:harvest_bush":1}');
insert into class_perk values ('forester_choice_logs', 'forester', 6, 5, 'Choice Logs', 'Logs from a tree you fell come up at +10% QL.', '{"ql:cut_down":1.1}');
insert into class_perk values ('forester_rare_heartwood', 'forester', 6, 6, 'Rare Heartwood', '1 in 100 trees you fell give rare logs, rolling on to supreme and fantastic at the odds crafting has. Felled logs are never rare without it.', '{"rare:cut_down":0.01}');
insert into class_perk values ('forester_master_grafter', 'forester', 6, 14, 'Master Grafter', 'Graft never fails (now a check at difficulty 40, and the sprout is spent either way) and takes 30% less time (8 s base).', '{"fail:graft":0,"time:graft":0.7}');
insert into class_perk values ('farmer_fodder', 'farmer', 1, 14, 'Fodder', 'Every crop you harvest also gives two mixed grass, at the harvest''s QL, into your pack.', '{"fodder:harvest_crop":2}');
insert into class_perk values ('farmer_milkmaid', 'farmer', 1, 25, 'Milkmaid', 'Milking takes 40% less time (6 s base), and 1 in 2 goes fill a second bucket of milk, if you carry another empty bucket.', '{"time:milk_creature":0.6,"more:milk_creature":0.5}');
insert into class_perk values ('farmer_sack_porter', 'farmer', 1, 28, 'Sack Porter', 'The produce and seed of every crop, flour and cornmeal weigh 50% less in your pack: potato 0.1 kg a unit (now 0.2 kg), wheat seeds 0.01 kg a unit (now 0.02 kg) and flour 0.05 kg a unit (now 0.1 kg).', '{"weight:onion":0.5,"weight:onion_seed":0.5,"weight:carrot":0.5,"weight:carrot_seed":0.5,"weight:cabbage":0.5,"weight:cabbage_seed":0.5,"weight:potato":0.5,"weight:potato_seed":0.5,"weight:wheat":0.5,"weight:wheat_seed":0.5,"weight:corn":0.5,"weight:corn_seed":0.5,"weight:sage":0.5,"weight:sage_seed":0.5,"weight:basil":0.5,"weight:basil_seed":0.5,"weight:thyme":0.5,"weight:thyme_seed":0.5,"weight:mint":0.5,"weight:mint_seed":0.5,"weight:rosemary":0.5,"weight:rosemary_seed":0.5,"weight:cotton":0.5,"weight:cotton_seed":0.5,"weight:wemp":0.5,"weight:wemp_seed":0.5,"weight:flour":0.5,"weight:cornmeal":0.5}');
insert into class_perk values ('farmer_seed_saver', 'farmer', 2, 4, 'Seed Saver', '1 in 4 fields you sow, with Sow or Sow a patch, use no seed.', '{"keep:plant_seed":0.25}');
insert into class_perk values ('farmer_fast_growth', 'farmer', 2, 5, 'Fast Growth', 'Each stage of a crop you sow takes 20% less time, from mint''s 100 s (now 125 s) to corn''s 300 s (now 375 s).', '{"grow:plant_seed":0.8}');
insert into class_perk values ('farmer_bumper_crop', 'farmer', 2, 8, 'Bumper Crop', 'A crop tended at all three stages gives 5 produce when you harvest it (now 4).', '{"bumper:harvest_crop":1}');
insert into class_perk values ('farmer_more_meal', 'farmer', 3, 22, 'More Meal', 'Grind into flour makes two flour a go (now one), and Grind into cornmeal two cornmeal (now one).', '{"count:flour":2,"count:cornmeal":2}');
insert into class_perk values ('farmer_full_press', 'farmer', 3, 23, 'Full Press', 'Pressing juice, cider or olive oil at the quern takes 20% less fruit, 8 where it took 10 and 16 where it took 20: 25% more from the same fruit. Juice and cider still take one bucket to a pressing.', '{"need:press_olives":0.8,"need:press_apple_juice":0.8,"need:press_cherry_juice":0.8,"need:press_olive_juice":0.8,"need:press_pear_juice":0.8,"need:press_plum_juice":0.8,"need:press_peach_juice":0.8,"need:press_fig_juice":0.8,"need:press_lemon_juice":0.8,"need:press_pomegranate_juice":0.8,"need:press_apricot_juice":0.8,"need:press_quince_juice":0.8,"need:press_apple_cider":0.8,"need:press_pear_cider":0.8}');
insert into class_perk values ('farmer_barn_reach', 'farmer', 3, 30, 'Barn Reach', 'What Harvest and Harvest a patch bring up goes into the nearest unlocked cart or wagon that nobody else is pulling or driving, or container you built or that stands on your settlement, within 5 tiles (now into your pack).', '{"into:harvest_crop":5,"into:harvest_patch":5}');
insert into class_perk values ('farmer_crop_rotation', 'farmer', 4, 6, 'Crop Rotation', 'Each stage of a crop you sow on a field last sown with a different crop takes 25% less time, from mint''s 93.8 s (now 125 s) to corn''s 281.3 s (now 375 s). A field never sown, or broken up since, has no last crop.', '{"rotate:plant_seed":0.75}');
insert into class_perk values ('farmer_worn_in_rake', 'farmer', 4, 34, 'Worn-in Rake', 'When you till, your rake counts as 20 QL better than it is, to at most 100. A tool takes one part in 400 of a go''s time off for each point of its QL, so that is 5% of Till''s time (5 s base).', '{"tool:till":20}');
insert into class_perk values ('farmer_sow_a_patch', 'farmer', 4, 39, 'Sow a Patch', 'Sow a patch (a job, 9 s, as long as three sowings): the seed you choose, sown on every empty field in the 3×3 tiles around the one you choose, one seed a field.', '{"sow_patch":1}');
insert into class_perk values ('farmer_rare_harvest', 'farmer', 5, 11, 'Rare Harvest', '1 in 100 crops you harvest come up rare, rolling on to supreme and fantastic at the odds crafting has; the seed does not. A harvest is never rare without it.', '{"rare:harvest_crop":0.01}');
insert into class_perk values ('farmer_tend_a_patch', 'farmer', 5, 40, 'Tend a Patch', 'Tend a patch (a job, 12 s, as long as three tendings): every crop in the 3×3 tiles around the one you choose that is not ripe and not yet tended at the stage it is at, tended.', '{"tend_patch":1}');
insert into class_perk values ('farmer_harvest_a_patch', 'farmer', 5, 41, 'Harvest a Patch', 'Harvest a patch (a job, 15 s, as long as three harvests): every ripe crop in the 3×3 tiles around the one you choose, harvested, each for what its own tending earned.', '{"harvest_patch":1}');
insert into class_perk values ('farmer_herb_plot', 'farmer', 6, 15, 'Herb Plot', 'Sage, basil, thyme, mint and rosemary give two more each time you harvest one.', '{"plus:sage":2,"plus:basil":2,"plus:thyme":2,"plus:mint":2,"plus:rosemary":2}');
insert into class_perk values ('farmer_grain_master', 'farmer', 6, 16, 'Grain Master', 'Wheat and corn give two more each time you harvest one.', '{"plus:wheat":2,"plus:corn":2}');
insert into class_perk values ('farmer_fibre_farmer', 'farmer', 6, 17, 'Fibre Farmer', 'Cotton and wemp give two more each time you harvest one.', '{"plus:cotton":2,"plus:wemp":2}');
insert into class_perk values ('cook_flavoursome', 'cook', 1, 11, 'Flavoursome', 'The knack from a dish you cooked lasts 50% longer, whoever eats it.', '{"knack:cheese":1.5,"knack:cooked_meat":1.5,"knack:baked_potato":1.5,"knack:roast_onion":1.5,"knack:roast_nuts":1.5,"knack:roast_lotus_seeds":1.5,"knack:berry_compote":1.5,"knack:pottage":1.5,"knack:preserves":1.5,"knack:bread":1.5,"knack:porridge":1.5,"knack:apple_pie":1.5,"knack:broth":1.5,"knack:stew":1.5,"knack:cooked_fish":1.5}');
insert into class_perk values ('cook_full_carcass', 'cook', 1, 18, 'Full Carcass', 'You take 15% more of a carcass you butcher, and never more than all of it.', '{"share:butcher":1.15}');
insert into class_perk values ('cook_strong_brew', 'cook', 1, 28, 'Strong Brew', 'The knack from ale, cider, mead and wine you brewed lasts 50% longer, whoever drinks it, from the barrel or from a bucket drawn off it.', '{"brewed:ale":1.5,"brewed:cider":1.5,"brewed:mead":1.5,"brewed:wine":1.5}');
insert into class_perk values ('cook_pantry_reach', 'cook', 2, 31, 'Pantry Reach', 'Cooking takes what goes into it from containers within 6 tiles (now 3).', '{"reach:cook":6}');
insert into class_perk values ('cook_bait_maker', 'cook', 2, 49, 'Bait Maker', 'Butchering a carcass also gives two offal, a fishing bait that trout and pike bite on.', '{"bait:butcher":2}');
insert into class_perk values ('cook_taste', 'cook', 2, 50, 'Taste', 'Examine on food or drink says how much of the food bar a helping fills (or of the thirst bar it quenches), how much of each of the four it feeds, and how long its knack lasts, at its quality and with its maker''s hand in it.', '{"taste":1}');
insert into class_perk values ('cook_fine_fare', 'cook', 3, 3, 'Fine Fare', 'Dishes you cook come up at +10% QL: every one of the 21 cooking recipes that make food.', '{"ql:make_cheese":1.1,"ql:cook_meat":1.1,"ql:bake_potato":1.1,"ql:roast_onion":1.1,"ql:roast_nuts":1.1,"ql:roast_lotus_seeds":1.1,"ql:make_compote":1.1,"ql:fry_meat":1.1,"ql:make_pottage":1.1,"ql:make_preserves":1.1,"ql:bake_bread":1.1,"ql:make_porridge":1.1,"ql:make_apple_pie":1.1,"ql:make_cherry_preserves":1.1,"ql:make_broth":1.1,"ql:make_stew":1.1,"ql:cook_minnow":1.1,"ql:cook_perch":1.1,"ql:cook_trout":1.1,"ql:cook_pike":1.1,"ql:cook_sturgeon":1.1}');
insert into class_perk values ('cook_hearty', 'cook', 3, 7, 'Hearty', 'Dishes you cook feed each of the four they feed 25% more, whoever eats them.', '{"feed:cheese":1.25,"feed:cooked_meat":1.25,"feed:baked_potato":1.25,"feed:roast_onion":1.25,"feed:roast_nuts":1.25,"feed:roast_lotus_seeds":1.25,"feed:berry_compote":1.25,"feed:pottage":1.25,"feed:preserves":1.25,"feed:bread":1.25,"feed:porridge":1.25,"feed:apple_pie":1.25,"feed:broth":1.25,"feed:stew":1.25,"feed:cooked_fish":1.25}');
insert into class_perk values ('cook_long_lasting', 'cook', 3, 8, 'Long-lasting', 'Dishes you cook rot 50% slower lying on the ground, whoever sets them down. Nothing rots in a pack or a store.', '{"rot:cheese":0.5,"rot:cooked_meat":0.5,"rot:baked_potato":0.5,"rot:roast_onion":0.5,"rot:roast_nuts":0.5,"rot:roast_lotus_seeds":0.5,"rot:berry_compote":0.5,"rot:pottage":0.5,"rot:preserves":0.5,"rot:bread":0.5,"rot:porridge":0.5,"rot:apple_pie":0.5,"rot:broth":0.5,"rot:stew":0.5,"rot:cooked_fish":0.5}');
insert into class_perk values ('cook_big_pot', 'cook', 4, 5, 'Big Pot', 'Stew, pottage, porridge and preserves each make one more a go: stew two (now one), pottage three (now two), porridge three (now two) and preserves three (now two).', '{"count:stew":2,"count:pottage":3,"count:porridge":3,"count:preserves":3}');
insert into class_perk values ('cook_frugal_cook', 'cook', 4, 6, 'Frugal Cook', '1 in 5 dishes you cook give back one of their first ingredient, other than a bucket, at the quality of the stack it came off.', '{"keep:make_cheese":0.2,"keep:cook_meat":0.2,"keep:bake_potato":0.2,"keep:roast_onion":0.2,"keep:roast_nuts":0.2,"keep:roast_lotus_seeds":0.2,"keep:make_compote":0.2,"keep:fry_meat":0.2,"keep:make_pottage":0.2,"keep:make_preserves":0.2,"keep:bake_bread":0.2,"keep:make_porridge":0.2,"keep:make_apple_pie":0.2,"keep:make_cherry_preserves":0.2,"keep:make_broth":0.2,"keep:make_stew":0.2,"keep:cook_minnow":0.2,"keep:cook_perch":0.2,"keep:cook_trout":0.2,"keep:cook_pike":0.2,"keep:cook_sturgeon":0.2}');
insert into class_perk values ('cook_filling', 'cook', 4, 15, 'Filling', 'Dishes you cook fill 25% more of the food bar, whoever eats them.', '{"fill:cheese":1.25,"fill:cooked_meat":1.25,"fill:baked_potato":1.25,"fill:roast_onion":1.25,"fill:roast_nuts":1.25,"fill:roast_lotus_seeds":1.25,"fill:berry_compote":1.25,"fill:pottage":1.25,"fill:preserves":1.25,"fill:bread":1.25,"fill:porridge":1.25,"fill:apple_pie":1.25,"fill:broth":1.25,"fill:stew":1.25,"fill:cooked_fish":1.25}');
insert into class_perk values ('cook_prime_cuts', 'cook', 5, 20, 'Prime Cuts', 'Meat you butcher comes up at +10% QL.', '{"ql:meat":1.1}');
insert into class_perk values ('cook_hide_keeper', 'cook', 5, 21, 'Hide Keeper', 'Hides, furs and bones you butcher come up at +10% QL.', '{"ql:hide":1.1,"ql:fur":1.1,"ql:bone":1.1}');
insert into class_perk values ('cook_cool_pack', 'cook', 5, 32, 'Cool Pack', 'Food you drop rots 50% slower where it lies, until it is picked up. Nothing rots in a pack.', '{"cool:food":0.5}');
insert into class_perk values ('cook_balanced_diet', 'cook', 6, 14, 'Balanced Diet', 'A full table is worth up to 30% more on everything you learn (now 20%).', '{"table:best":0.3}');
insert into class_perk values ('cook_broth', 'cook', 6, 46, 'Broth', 'A new recipe, Boil a broth: two bones and one bucket of water over a campfire make two broth, each feeding all four a little: flesh 8%, starch 8%, greens 8% and fat 8% at QL 100.', '{"broth":1}');
insert into class_perk values ('cook_distil', 'cook', 6, 47, 'Distil', 'A new recipe for each brew: three buckets of it (15 litres) boiled off over a campfire into one of spirit (5 litres), and two buckets back. A drink of spirit at QL 100 gives a knack that lasts seven hours (ale an hour and fifty-eight minutes, cider two and a quarter hours, mead two and a quarter hours and wine two and a quarter hours).', '{"distil":1}');
insert into class_perk values ('tailor_full_fleece', 'tailor', 1, 2, 'Full Fleece', 'Shearing gives one more wool a go (now one to three, by how grown the fleece is).', '{"plus:wool":1}');
insert into class_perk values ('tailor_quick_spindle', 'tailor', 1, 3, 'Quick Spindle', 'Spinning takes 40% less time (6 s base), wool, cotton and wemp alike.', '{"time:spin_wool":0.6,"time:spin_cotton":0.6,"time:spin_wemp":0.6}');
insert into class_perk values ('tailor_sure_tan', 'tailor', 1, 18, 'Sure Tan', 'Tan in lye fails half as often (now a check at difficulty 16).', '{"fail:tan_hide":0.5}');
insert into class_perk values ('tailor_saddler', 'tailor', 2, 27, 'Saddler', 'A mount in a saddle or a bridle you stitched goes 10% faster, up to 5.5 tiles a second (now at most 5); and a cart or a wagon built with yokes you stitched goes 10% faster behind its team, over what its builder''s hand puts into it. Whoever rides or drives them.', '{"speed:saddle":1.1,"speed:bridle":1.1,"speed:yoke":1.1}');
insert into class_perk values ('tailor_fishers_friend', 'tailor', 2, 31, 'Fisher''s Friend', 'Nets and creels you make catch 20% more, whoever fishes with them: a net''s haul, and a creel''s chance of a fish each time it is looked at.', '{"catch:fishing_net":1.2,"catch:creel":1.2}');
insert into class_perk values ('tailor_workshop_reach', 'tailor', 2, 37, 'Workshop Reach', 'Tailoring, leatherworking and ropemaking take what goes into them from containers within 6 tiles (now 3).', '{"reach:tailor":6}');
insert into class_perk values ('tailor_sure_needle', 'tailor', 3, 9, 'Sure Needle', 'Tailoring fails half as often (now a check at difficulty 8–20).', '{"fail:make_rug":0.5,"fail:spin_wool":0.5,"fail:spin_cotton":0.5,"fail:spin_wemp":0.5,"fail:weave_cloth":0.5,"fail:make_needle":0.5,"fail:make_sack":0.5,"fail:make_wool_cap":0.5,"fail:make_cloth_tunic":0.5,"fail:make_cloth_sleeves":0.5,"fail:make_cloth_trousers":0.5,"fail:make_cloth_shoes":0.5,"fail:make_tent":0.5,"fail:make_banner":0.5,"fail:make_flagpole":0.5}');
insert into class_perk values ('tailor_lye_saver', 'tailor', 3, 19, 'Lye Saver', '1 in 2 tannings leave the lye in the bucket for another (now the bucket comes back empty).', '{"lye:tan_hide":0.5}');
insert into class_perk values ('tailor_sure_awl', 'tailor', 3, 21, 'Sure Awl', 'Leatherworking fails half as often (now a check at difficulty 12–58).', '{"fail:make_toolbelt":0.5,"fail:make_scale_helm":0.5,"fail:make_scale_cuirass":0.5,"fail:make_scale_sleeves":0.5,"fail:make_scale_leggings":0.5,"fail:make_scale_boots":0.5,"fail:make_satchel":0.5,"fail:make_backpack":0.5,"fail:make_awl":0.5,"fail:make_leather_cap":0.5,"fail:make_leather_jerkin":0.5,"fail:make_leather_sleeves":0.5,"fail:make_leather_trousers":0.5,"fail:make_leather_boots":0.5,"fail:make_saddle":0.5,"fail:make_bridle":0.5,"fail:make_yoke":0.5,"fail:tan_hide":0.5}');
insert into class_perk values ('tailor_sack_maker', 'tailor', 4, 16, 'Sack Maker', 'Sacks you stitch hold 60 (now 40), whoever has them after.', '{"hold:sack":1.5}');
insert into class_perk values ('tailor_deep_pockets', 'tailor', 4, 25, 'Deep Pockets', 'Satchels you stitch hold 31 (now 25) and backpacks 75 (now 60), whoever has them after.', '{"hold:satchel":1.25,"hold:backpack":1.25}');
insert into class_perk values ('tailor_nothing_wasted', 'tailor', 4, 34, 'Nothing Wasted', 'A failed tailoring, leatherworking or ropemaking job keeps its materials (now they are lost), on every one of the 30 that lose them.', '{"spare:make_toolbelt":1,"spare:make_rug":1,"spare:make_scale_helm":1,"spare:make_scale_cuirass":1,"spare:make_scale_sleeves":1,"spare:make_scale_leggings":1,"spare:make_scale_boots":1,"spare:make_net":1,"spare:make_creel":1,"spare:make_rope":1,"spare:make_thick_rope":1,"spare:spin_wool":1,"spare:spin_cotton":1,"spare:spin_wemp":1,"spare:weave_cloth":1,"spare:make_needle":1,"spare:make_sack":1,"spare:make_satchel":1,"spare:make_backpack":1,"spare:make_awl":1,"spare:make_leather_cap":1,"spare:make_leather_jerkin":1,"spare:make_leather_sleeves":1,"spare:make_leather_trousers":1,"spare:make_leather_boots":1,"spare:make_saddle":1,"spare:make_bridle":1,"spare:make_yoke":1,"spare:make_torch":1,"spare:tan_hide":1}');
insert into class_perk values ('tailor_even_thread', 'tailor', 5, 4, 'Even Thread', 'Spinning makes three yarn a go (now two) from the same two fibre.', '{"count:yarn":3}');
insert into class_perk values ('tailor_tight_weave', 'tailor', 5, 7, 'Tight Weave', 'Weave cloth takes two yarn (now three).', '{"need:weave_cloth":0.6666666666666666}');
insert into class_perk values ('tailor_light_pack', 'tailor', 5, 35, 'Light Pack', 'Cloth, leather, yarn and hides weigh 50% less in your pack: cloth 0.15 kg a unit (now 0.3 kg), leather 0.75 kg a unit (now 1.5 kg), yarn 0.075 kg a unit (now 0.15 kg) and hide 1 kg a unit (now 2 kg).', '{"weight:cloth":0.5,"weight:leather":0.5,"weight:yarn":0.5,"weight:hide":0.5}');
insert into class_perk values ('tailor_master_tailor', 'tailor', 6, 11, 'Master Tailor', 'What you tailor, all 15 things, comes out rare 1 in 50 (now 1 in 100); supreme and fantastic follow at their usual odds.', '{"rare:make_rug":0.02,"rare:spin_wool":0.02,"rare:spin_cotton":0.02,"rare:spin_wemp":0.02,"rare:weave_cloth":0.02,"rare:make_needle":0.02,"rare:make_sack":0.02,"rare:make_wool_cap":0.02,"rare:make_cloth_tunic":0.02,"rare:make_cloth_sleeves":0.02,"rare:make_cloth_trousers":0.02,"rare:make_cloth_shoes":0.02,"rare:make_tent":0.02,"rare:make_banner":0.02,"rare:make_flagpole":0.02}');
insert into class_perk values ('tailor_patch', 'tailor', 6, 46, 'Patch', 'Patch (a job, 4 s): 20 damage off a cloth or leather piece for one cloth or one leather, and nothing off its QL.', '{"patch_item":20}');
insert into class_perk values ('tailor_tent', 'tailor', 6, 49, 'Tent', 'A new piece to build, a tent (eight cloth, two ropes and three shafts, with a needle), that you can set down anywhere and sleep in: 50% of the rest a bed gives.', '{"tent":1}');
insert into class_perk values ('herdsman_soft_hand', 'herdsman', 1, 1, 'Soft Hand', 'Every offering to tame a wildermon is 10 percentage points likelier to take, over everything else that goes into the chance (still 95% at most).', '{"tame:offer":0.1}');
insert into class_perk values ('herdsman_brushwork', 'herdsman', 1, 11, 'Brushwork', 'A brushing puts 50% more care in (now 18% to 74% of full care, by your husbandry and the brush).', '{"groom:care":1.5}');
insert into class_perk values ('herdsman_short_rest', 'herdsman', 1, 21, 'Short Rest', 'A pair you put together can be put to a mate again twenty-five minutes after (now fifty minutes), and half that after a pairing that did not take (now twenty-five minutes).', '{"breed:rest":0.5}');
insert into class_perk values ('herdsman_healing_hands', 'herdsman', 2, 15, 'Healing Hands', 'A brushing heals 15% of a wildermon''s health (now 6%).', '{"groom:heal":0.15}');
insert into class_perk values ('herdsman_light_crate', 'herdsman', 2, 37, 'Light Crate', 'A creature crate weighs 3 kg in your pack (now 10 kg).', '{"weight:creature_crate":0.3}');
insert into class_perk values ('herdsman_stud_book', 'herdsman', 2, 50, 'Stud Book', 'Examine on one of yours says, for the mate it would be put to, how often the pairing takes and how often each of the young''s traits is drawn from their blood and comes out a tier better.', '{"stud_book":1}');
insert into class_perk values ('herdsman_patient_coax', 'herdsman', 3, 2, 'Patient Coax', 'Each offering a wildermon refuses makes the next 6 percentage points likelier (now 3 percentage points).', '{"coax:step":0.06}');
insert into class_perk values ('herdsman_lasting_care', 'herdsman', 3, 13, 'Lasting Care', 'The care in a wildermon you keep wears off over six hours (now three hours), whoever brushed it.', '{"kept:care_hours":6}');
insert into class_perk values ('herdsman_quick_gestation', 'herdsman', 3, 22, 'Quick Gestation', 'A mother you pair carries for a quarter of an hour (now half an hour).', '{"breed:gestation":0.5}');
insert into class_perk values ('herdsman_young_trust', 'herdsman', 4, 9, 'Young Trust', 'A young wildermon is 2.5 times as easy to tame as a grown one (now 1.6 times).', '{"tame:young":2.5}');
insert into class_perk values ('herdsman_light_eaters', 'herdsman', 4, 16, 'Light Eaters', 'Wildermon you keep get hungry 30% slower: one following you goes from fed to empty in an hour and thirty-five minutes (now an hour and seven minutes), one working a settlement in an hour (now forty-two minutes).', '{"kept:hunger":0.7}');
insert into class_perk values ('herdsman_true_blood', 'herdsman', 4, 25, 'True Blood', 'Each of a young one''s three traits is 10 percentage points likelier to be drawn from its parents'' blood (now 50%, plus 0.35 of a point for each husbandry level and up to 11 percentage points for their care, 96% at most), and never past certain.', '{"breed:inherit":0.1}');
insert into class_perk values ('herdsman_well_kept', 'herdsman', 5, 14, 'Well Kept', 'A wildermon you keep works and learns 40% faster brushed to a shine (now 25%), and its share of that at less care: 20% at half.', '{"kept:care_bonus":0.4}');
insert into class_perk values ('herdsman_twins', 'herdsman', 5, 24, 'Twins', '1 in 5 pairings give a second young as well, bred for itself from the pair.', '{"breed:twins":0.2}');
insert into class_perk values ('herdsman_choose_the_sex', 'herdsman', 5, 28, 'Choose the Sex', 'You choose whether a pairing gives a male or a female young (now even odds), twins alike.', '{"breed:sex":1}');
insert into class_perk values ('herdsman_any_bait', 'herdsman', 6, 10, 'Any Bait', 'Any food will do as an offering to tame any kind (now each kind takes only its own few). Feeding one you keep still takes its own.', '{"bait:any":1}');
insert into class_perk values ('herdsman_long_lived', 'herdsman', 6, 18, 'Long-lived', 'Wildermon you keep grow old at twenty-five hours (now fifteen hours).', '{"kept:old_at":90000}');
insert into class_perk values ('herdsman_bred_up', 'herdsman', 6, 26, 'Bred Up', 'Each of a young one''s traits is 10 percentage points likelier to come out a tier better (now 0.22 of a point for each husbandry level and up to 8 percentage points for their care, 30% at most).', '{"breed:upgrade":0.1}');
insert into class_perk values ('naturalist_keen_eye', 'naturalist', 1, 2, 'Keen Eye', 'Foraging and botanizing go over the ground one more time a go (now once, and once more for every 20 points of the skill).', '{"passes:forage":1,"passes:botanize":1}');
insert into class_perk values ('naturalist_quick_lye', 'naturalist', 1, 13, 'Quick Lye', 'Making lye takes 40% less time (12 s base).', '{"time:make_lye":0.6}');
insert into class_perk values ('naturalist_quick_dressing', 'naturalist', 1, 23, 'Quick Dressing', 'Dressing a wound takes 40% less time (7 s base).', '{"time:bind_wound":0.6}');
insert into class_perk values ('naturalist_hay_cutter', 'naturalist', 2, 10, 'Hay Cutter', 'Cutting grass gives three bundles (now two).', '{"count:mixed_grass":3}');
insert into class_perk values ('naturalist_reed_cutter', 'naturalist', 2, 11, 'Reed Cutter', 'Cutting reeds always gives three (now two, and one more on a chance of your foraging in 140).', '{"count:reed":3}');
insert into class_perk values ('naturalist_ink_maker', 'naturalist', 2, 19, 'Ink Maker', 'Grinding ink makes four (now two).', '{"count:ink":4}');
insert into class_perk values ('naturalist_sure_find', 'naturalist', 3, 3, 'Sure Find', 'No look over the ground comes up empty by chance, foraging or botanizing (now 1 in 5 does, before the skill is asked).', '{"empty:forage":0,"empty:botanize":0}');
insert into class_perk values ('naturalist_sure_boil', 'naturalist', 3, 17, 'Sure Boil', 'Alchemy fails half as often (now a check at difficulty 10–22).', '{"fail:make_candle":0.5,"fail:make_lye":0.5,"fail:make_ink":0.5,"fail:make_woad":0.5,"fail:make_madder":0.5,"fail:make_scarlet":0.5,"fail:make_cochineal":0.5,"fail:make_gall":0.5,"fail:make_weld":0.5,"fail:make_verdigris":0.5,"fail:make_umber":0.5,"fail:make_rose":0.5,"fail:make_lavender":0.5,"fail:make_wildflowers":0.5,"fail:make_lily":0.5,"fail:make_lotus":0.5,"fail:brew_tea_thyme":0.5,"fail:make_tincture_thyme":0.5,"fail:brew_tea_basil":0.5,"fail:make_tincture_basil":0.5,"fail:brew_tea_mint":0.5,"fail:make_tincture_mint":0.5,"fail:brew_tea_sage":0.5,"fail:make_tincture_sage":0.5,"fail:brew_tea_rosemary":0.5,"fail:make_tincture_rosemary":0.5}');
insert into class_perk values ('naturalist_sure_hands', 'naturalist', 3, 24, 'Sure Hands', 'A dressing slips half as often (now a check at difficulty 10).', '{"fail:bind_wound":0.5}');
insert into class_perk values ('naturalist_thrifty_dyer', 'naturalist', 4, 16, 'Thrifty Dyer', 'A dye boil takes 6–8 of its dyestuff (now 8–10), and the one bucket of lye.', '{"need:make_woad":0.75,"need:make_madder":0.75,"need:make_scarlet":0.75,"need:make_cochineal":0.75,"need:make_gall":0.75,"need:make_weld":0.75,"need:make_verdigris":0.75,"need:make_umber":0.75,"need:make_rose":0.75,"need:make_lavender":0.75,"need:make_wildflowers":0.75,"need:make_lily":0.75,"need:make_lotus":0.75}');
insert into class_perk values ('naturalist_quick_mend', 'naturalist', 4, 29, 'Quick Mend', 'A wound you dress closes 50% faster until it closes or is cleaned out, whoever''s it is.', '{"mend:bind_wound":1.5}');
insert into class_perk values ('naturalist_cover_maker', 'naturalist', 4, 30, 'Cover Maker', 'Two of one herb and one cotton make five healing covers (now three).', '{"count:cover":5}');
insert into class_perk values ('naturalist_rare_find', 'naturalist', 5, 12, 'Rare Find', '1 in 100 finds foraging or botanizing come up rare (now none do); supreme and fantastic follow at their usual odds.', '{"rare:forage":0.01,"rare:botanize":0.01}');
insert into class_perk values ('naturalist_double_boil', 'naturalist', 5, 15, 'Double Boil', 'A dye boil makes three pots (now two).', '{"count:dye":3}');
insert into class_perk values ('naturalist_field_medic', 'naturalist', 5, 34, 'Field Medic', 'You can dress the wounds of somebody standing beside you, at your first aid and with your dressings (now only your own).', '{"dress_others":1}');
insert into class_perk values ('naturalist_herb_tea', 'naturalist', 6, 43, 'Herb Tea', 'A new recipe: two of one herb and a bucket of water make three cups of herb tea, and a cup puts back 20% of your stamina.', '{"herb_tea":1}');
insert into class_perk values ('naturalist_salve', 'naturalist', 6, 44, 'Salve', 'A new recipe: two of one herb and one beeswax make a salve. Rubbed in over a dressing, the wound under it never goes bad (now cloth over it leaves 12% of the chance and the wrong herb 5%).', '{"salve":1}');
insert into class_perk values ('naturalist_tincture', 'naturalist', 6, 50, 'Tincture', 'A new recipe: three of one herb make a tincture. Taken, foraging, botanizing, alchemy and first aid each go in 10% faster for fifty minutes, beside anything a dish is doing for them.', '{"tincture":1}');
insert into class_perk values ('fisher_quick_cast', 'fisher', 1, 1, 'Quick Cast', 'A cast takes 30% less time (9 s base).', '{"time:fish":0.7}');
insert into class_perk values ('fisher_bait_saver', 'fisher', 1, 4, 'Bait Saver', 'A fish that comes off leaves your bait on the hook, so bait goes only with a fish you land (now every cast with bait on takes it).', '{"spare:fish":1}');
insert into class_perk values ('fisher_quick_net', 'fisher', 1, 13, 'Quick Net', 'Dragging the net takes 30% less time (16 s base).', '{"time:drag_net":0.7}');
insert into class_perk values ('fisher_long_cast', 'fisher', 2, 2, 'Long Cast', 'Your line reaches water 6 tiles off (now 3.6); click water further than that and it goes into the deepest water within 6 tiles of you each way (now 3).', '{"reach:fish":6}');
insert into class_perk values ('fisher_wide_net', 'fisher', 2, 15, 'Wide Net', 'Your net reaches water 4 tiles off (now 2.6); click water further than that and it is dragged through the deepest water within 4 tiles of you each way (now 2).', '{"reach:drag_net":4}');
insert into class_perk values ('fisher_fishing_journal', 'fisher', 2, 45, 'Fishing Journal', 'Examining water also says how deep it is, what share of the bites there each fish you could land is with the bait you would put on, and how often a fish that bites stays on with your rod.', '{"fish_journal":1}');
insert into class_perk values ('fisher_net_care', 'fisher', 3, 17, 'Net Care', 'A fishing net takes half the damage a drag, at any quality.', '{"wear:fishing_net":0.5}');
insert into class_perk values ('fisher_cool_pack', 'fisher', 3, 25, 'Cool Pack', 'Minnow, perch, trout, pike and sturgeon you drop rot 50% slower where they lie, until they are picked up. Nothing rots in a pack.', '{"cool:minnow":0.5,"cool:perch":0.5,"cool:trout":0.5,"cool:pike":0.5,"cool:sturgeon":0.5}');
insert into class_perk values ('fisher_rod_care', 'fisher', 3, 33, 'Rod Care', 'A fishing rod takes half the damage a cast, at any quality and of any wood.', '{"wear:fishing_rod":0.5}');
insert into class_perk values ('fisher_steady_hand', 'fisher', 4, 3, 'Steady Hand', 'A fish that bites stays on 15 percentage points more often, over everything else that goes into it (still 95% at most).', '{"hook:fish":0.15}');
insert into class_perk values ('fisher_full_net', 'fisher', 4, 14, 'Full Net', 'A drag of the net hauls 2 more fish: 3 to 7 by the net''s quality (now 1 to 5), before its maker''s mark is counted in.', '{"haul:drag_net":2}');
insert into class_perk values ('fisher_deep_creel', 'fisher', 4, 19, 'Deep Creel', 'A creel you make holds 16 fish before it takes no more (now 8).', '{"hold:creel":2}');
insert into class_perk values ('fisher_strong_bait', 'fisher', 5, 5, 'Strong Bait', 'Bait draws the fish it favours twice as hard, on the hook and in a creel you set: 16 times its plain weight for the first it favours and 8 for the second (now 8 and 4).', '{"bait:pull":2}');
insert into class_perk values ('fisher_any_bait', 'fisher', 5, 6, 'Any Bait', 'With no bait that draws a fish in your pack, any food goes on the hook or in a creel instead: it draws every fish at its plain weight, and a fish on it stays on 12 percentage points more often, as on any bait (now only worms, corn, minnow, meat, perch or offal will do).', '{"bait:food":1}');
insert into class_perk values ('fisher_big_fish', 'fisher', 5, 9, 'Big Fish', 'Trout, pike and sturgeon weigh twice as much in the draw of which fish bites, on your rod, in your net and in a creel you set: where every fish runs and nothing is on the hook, they are 50.9% of the bites (now 34.1%).', '{"bite:trout":2,"bite:pike":2,"bite:sturgeon":2}');
insert into class_perk values ('fisher_rare_catch', 'fisher', 6, 12, 'Rare Catch', '1 in 100 fish you land on a rod or haul in a net come up rare (now none do); supreme and fantastic follow at their usual odds.', '{"rare:fish":0.01,"rare:drag_net":0.01}');
insert into class_perk values ('fisher_smoke_fish', 'fisher', 6, 27, 'Smoke Fish', 'A new recipe: a fish hung in the smoke of a lit campfire, at your fishing, comes off at its own quality and rots 80% slower wherever it is left: it keeps five times as long.', '{"smoke_fish":1,"rot:minnow":0.2,"rot:perch":0.2,"rot:trout":0.2,"rot:pike":0.2,"rot:sturgeon":0.2}');
insert into class_perk values ('fisher_fish_pond', 'fisher', 6, 47, 'Fish Pond', 'A new piece to build, a fish pond (twenty clay, twelve rock shards and eight reeds, with a shovel), that you set down on your settlement: it stocks itself at a fish in an hour until it holds 10, drawn from every fish at its plain weight.', '{"fish_pond":1}');
insert into class_perk values ('mender_quick_hands', 'mender', 1, 4, 'Quick Hands', 'Each go of Repair takes 40% less time: 2.7 s, where it takes 4.5 s now, the shortest any job takes without a perk on it.', '{"time:repair_item":0.6}');
insert into class_perk values ('mender_tool_care', 'mender', 1, 9, 'Tool Care', 'Every tool you work with wears 25% slower: each use puts that much less damage on it, whatever the job and whatever the tool is made of.', '{"wear:awl":0.75,"wear:brush":0.75,"wear:butchering_knife":0.75,"wear:carving_knife":0.75,"wear:chisel":0.75,"wear:clay_bowl":0.75,"wear:clay_jar":0.75,"wear:clay_pot":0.75,"wear:file":0.75,"wear:fishing_net":0.75,"wear:fishing_rod":0.75,"wear:frying_pan":0.75,"wear:hammer":0.75,"wear:hatchet":0.75,"wear:mallet":0.75,"wear:needle":0.75,"wear:pickaxe":0.75,"wear:quern":0.75,"wear:rake":0.75,"wear:rope_tool":0.75,"wear:saw":0.75,"wear:shovel":0.75,"wear:sickle":0.75,"wear:trowel":0.75}');
insert into class_perk values ('mender_quick_restore', 'mender', 1, 17, 'Quick Restore', 'Restoring a relic or a bauble takes 40% less time (20 s base).', '{"time:restore_relic":0.6}');
insert into class_perk values ('mender_clean_repair', 'mender', 2, 3, 'Clean Repair', '1 in 4 goes of Repair take nothing off the quality of what they mend.', '{"keep:repair_item":0.25}');
insert into class_perk values ('mender_armour_care', 'mender', 2, 10, 'Armour Care', 'Armour you wear takes 25% less damage from each blow that lands on it, a shield 25% less from each blow it stops, and a weapon 25% less from each blow it lands or arrow it puts home.', '{"worn:armour":0.75,"worn:shield":0.75,"worn:weapon":0.75}');
insert into class_perk values ('mender_gentle_hands', 'mender', 2, 19, 'Gentle Hands', 'A restoring that fails does no damage to the pieces or the bauble (now 5 to 14 to each).', '{"harm:restore_relic":0}');
insert into class_perk values ('mender_big_mend', 'mender', 3, 1, 'Big Mend', 'Each go of Repair takes 50% more damage out, for the same quality on each point of it: 12.3 at repair 70 (now 8.2).', '{"mend:repair_item":1.5}');
insert into class_perk values ('mender_post_keeper', 'mender', 3, 14, 'Post Keeper', 'Work posts, snares, creels and deadfalls you set stand 50% longer: a work post an hour and fifty-three minutes to four and a half hours by its quality (now an hour and a quarter to three hours).', '{"life:work_post":1.5,"life:snare":1.5,"life:creel":1.5,"life:deadfall":1.5}');
insert into class_perk values ('mender_sure_restore', 'mender', 3, 18, 'Sure Restore', 'Restoring a relic or a bauble fails half as often.', '{"fail:restore_relic":0.5}');
insert into class_perk values ('mender_light_touch', 'mender', 4, 2, 'Light Touch', 'Repairing takes half the quality off for each point of damage it takes out: 0.0046 QL a point at repair 80 (now 0.0092).', '{"cost:repair_item":0.5}');
insert into class_perk values ('mender_fine_restore', 'mender', 4, 20, 'Fine Restore', 'What you restore comes out 10% higher in quality than it would, a relic or a bauble, to 100 at most.', '{"ql:restore_relic":1.1}');
insert into class_perk values ('mender_age_undone', 'mender', 4, 21, 'Age Undone', 'The damage on the pieces or the bauble takes nothing off the quality of what you restore (now each point of it takes 0.5% off).', '{"age:restore_relic":0}');
insert into class_perk values ('mender_lucky_polish', 'mender', 5, 24, 'Lucky Polish', '1 in 50 baubles you restore come out rare (now 1 in 100); supreme and fantastic follow at their usual odds.', '{"rare:restore_relic":0.02}');
insert into class_perk values ('mender_second_look', 'mender', 5, 25, 'Second Look', 'A minor or major bauble you restore is rolled twice and keeps whichever roll gives the most (each gives 1 to 5% before its rarity); an ancient one gives the same whichever it keeps.', '{"rolls:bauble":2}');
insert into class_perk values ('mender_repair_kit', 'mender', 5, 42, 'Repair Kit', 'A new recipe, on repair: two cloth, two nails and one plank, with a hammer, make a repair kit, which takes 50 damage off anything in one use, anywhere, and none of its quality. Anybody may use one.', '{"repair_kit":1}');
insert into class_perk values ('mender_tier_up', 'mender', 6, 26, 'Tier Up', '1 in 10 baubles you restore come out a tier better than they went in: a minor one major and a major one ancient.', '{"tier:restore_relic":0.1}');
insert into class_perk values ('mender_handyman', 'mender', 6, 27, 'Handyman', 'You can improve anything to QL 30, whatever your skill in its trade (now 10); past that your skill is the ceiling, as it is for everybody.', '{"floor:improve":30}');
insert into class_perk values ('mender_sealant', 'mender', 6, 50, 'Sealant', 'A new recipe, on repair: one tar and one beeswax make sealant, and a thing it is worked over never decays after, wherever it is left: one to a thing, and one for each thing in a pile. Anybody may use it.', '{"sealant":1}');
insert into class_perk values ('artisan_sure_setting', 'artisan', 1, 2, 'Sure Setting', 'Setting a stone in a ring, a pendant, a focus or a circlet fails half as often.', '{"fail:set_ring":0.5,"fail:set_pendant":0.5,"fail:set_focus":0.5,"fail:set_in_circlet":0.5}');
insert into class_perk values ('artisan_keep_the_stone', 'artisan', 1, 3, 'Keep the Stone', 'A focus you fail to set gives you its stone back whole, and only the silver is lost (now the stone splits with it).', '{"stone:set_focus":1}');
insert into class_perk values ('artisan_deep_pot', 'artisan', 1, 26, 'Deep Pot', 'A pot or a bowl you shape makes 1 more serving of every dish cooked in it, whoever cooks it: cheese, berry compote, pottage, porridge, apple pie, preserves, broth and stew.', '{"serve:unfired_clay_pot":1,"serve:unfired_clay_bowl":1}');
insert into class_perk values ('artisan_cut_true', 'artisan', 2, 7, 'Cut True', 'A ring, a pendant or a circlet you make gives up to 5% more skill from every go at each stone''s trade, by its quality: all of it at QL 100 and half of it at QL 50 (now its quality makes no difference). A circlet''s stones each give half of it.', '{"cut:jewelled_ring":0.05,"cut:jewelled_pendant":0.05,"cut:circlet":0.05}');
insert into class_perk values ('artisan_fine_castings', 'artisan', 2, 9, 'Fine Castings', 'Rings and pendants you forge from a casting come off the anvil 10% higher in quality, to 100 at most.', '{"ql:ring":1.1,"ql:pendant":1.1}');
insert into class_perk values ('artisan_gem_eye', 'artisan', 2, 10, 'Gem Eye', 'Mine turns up a gem in 1 in 200 goes (now 1 in 400).', '{"gem:mine":0.005}');
insert into class_perk values ('artisan_focus_cutter', 'artisan', 3, 13, 'Focus Cutter', 'A focus you set wears 25% slower when a spell is cast from it, whoever casts it.', '{"thrift:focus":0.75}');
insert into class_perk values ('artisan_sealed_jar', 'artisan', 3, 27, 'Sealed Jar', 'What is put up in a jar you shape keeps twice as long, whoever puts it up: preserves.', '{"keeps:unfired_clay_jar":0.5}');
insert into class_perk values ('artisan_sturdy_binding', 'artisan', 3, 35, 'Sturdy Binding', 'A book you bind takes half the damage from a go of study (now 2 to 5 a go).', '{"sturdy:book":0.5,"sturdy:trade_book":0.5}');
insert into class_perk values ('artisan_bright_stone', 'artisan', 4, 4, 'Bright Stone', 'A ring or a pendant you make gives 15% more skill from every go at its stone''s trade (now 10%), and each stone in a circlet you make 7.5% (now 5%).', '{"bright:jewelled_ring":1.5,"bright:jewelled_pendant":1.5,"bright:circlet":1.5}');
insert into class_perk values ('artisan_keen_focus', 'artisan', 4, 14, 'Keen Focus', 'A spell cast from a focus you set is 10% stronger, and a hold it leaves lasts 10% longer, whoever casts it.', '{"force:focus":1.1}');
insert into class_perk values ('artisan_good_read', 'artisan', 4, 34, 'Good Read', 'A book you bind teaches 25% more from every go of study, whoever reads it.', '{"teach:book":1.25,"teach:trade_book":1.25}');
insert into class_perk values ('artisan_more_stones', 'artisan', 5, 12, 'More Stones', 'The rock gives up six more stones to you, and to nobody without this: an opal for taming, a peridot for farming, an amethyst for tailoring, a jasper for pottery, an onyx for masonry and an amber for cooking. Each is set and worn like any other stone.', '{"more_stones":1}');
insert into class_perk values ('artisan_amphora', 'artisan', 5, 46, 'Amphora', 'A new thing to shape, on pottery: four clay make an unfired amphora, which a kiln fires into an amphora that holds 20 of one food or drink at a time; what is in it rots at half the rate if it is left lying about. Anybody may fill one.', '{"amphora":1}');
insert into class_perk values ('artisan_potters_wheel', 'artisan', 5, 49, 'Potter''s Wheel', 'A new piece to build, a potter''s wheel (twelve planks, two shafts, a stone slab and twelve nails): anybody working at pottery within 2.4 tiles of it takes 30% less time a go, whatever else makes it quicker.', '{"potters_wheel":1}');
insert into class_perk values ('artisan_glaze', 'artisan', 6, 28, 'Glaze', 'A new job, Glaze it, on a clay pot, a clay bowl, a clay jar or an amphora: one lot of ashes brushed over it, and it never decays after, wherever it is left.', '{"glaze_item":1}');
insert into class_perk values ('artisan_trade_book', 'artisan', 6, 36, 'Trade Book', 'A new book to write, on papyrusmaking: six papyrus, two leather and two inks, with a needle, make a book on any craft trade you have 50 of, and studying it teaches that trade, as much a go as a plain book teaches mind logic. Anybody may read one.', '{"trade_book":1}');
insert into class_perk values ('artisan_circlet', 'artisan', 6, 48, 'Circlet', 'A new thing to make, on jewellery: two gold lumps, with a file, make a circlet, worn on the head in place of a helm. It takes three stones, set by anybody off each stone''s menu, and each gives half what it would in a ring: 5% more skill from every go at its trade.', '{"circlet":1}');
insert into class_perk values ('blade_measured_cut', 'blade', 1, 1, 'Measured Cut', 'Spell, 8% of your stamina, 6 s before it can be called again. A blow at 130% that cannot miss, on an enemy within your reach.', '{}');
insert into class_perk values ('blade_challenge', 'blade', 1, 32, 'Challenge', 'Spell, 8% of your stamina, 15 s before it can be called again. The creature turns on you at once and hunts only you for 10 s.', '{}');
insert into class_perk values ('blade_light_sword', 'blade', 1, 108, 'Light Sword', 'A swing of a sword costs 30% less stamina.', '{"wind:swords":0.7}');
insert into class_perk values ('blade_lunge', 'blade', 2, 2, 'Lunge', 'Spell, 10% of your stamina, 10 s before it can be called again. You stride to an enemy up to 4 tiles off, over ground you could walk, and strike it at 150%.', '{}');
insert into class_perk values ('blade_hamstring', 'blade', 2, 11, 'Hamstring', 'Spell, 10% of your stamina, 20 s before it can be called again. A blow at 80%; for 10 s it walks, hunts and flees at 50% of its pace.', '{}');
insert into class_perk values ('blade_counterweight', 'blade', 2, 111, 'Counterweight', 'A blow you block puts the next blow of whatever struck it back 0.5 s.', '{"stagger:block":0.5}');
insert into class_perk values ('blade_shield_bash', 'blade', 3, 15, 'Shield Bash', 'Spell, 10% of your stamina, 12 s before it can be called again. With a shield in your off hand: a crushing blow at 70% that knocks a heavy blow off its stroke and puts its next blow back 2 s.', '{}');
insert into class_perk values ('blade_second_breath', 'blade', 3, 29, 'Second Breath', 'Spell, 3 minutes before it can be called again. Costs no stamina. 40% of a full bar of stamina back at once.', '{}');
insert into class_perk values ('blade_battle_hardened', 'blade', 3, 127, 'Battle-Hardened', 'A blow that lands on you opens or deepens its wound 20% less, so it bleeds and slows you less. What it takes off your health is the same.', '{"severity:wound":0.8}');
insert into class_perk values ('blade_deflect', 'blade', 4, 19, 'Deflect', 'Spell, 10% of your stamina, 25 s before it can be called again. For 6 s, every blow you block lands back on what struck at 50% of the blow.', '{}');
insert into class_perk values ('blade_hold_the_line', 'blade', 4, 26, 'Hold the Line', 'Spell, 15% of your stamina, 90 s before it can be called again. For 15 s your wounds bleed 50% less, and those on your arms do not slow your swing.', '{}');
insert into class_perk values ('blade_stalwart', 'blade', 4, 123, 'Stalwart', 'In the defensive stance you take 30% less damage and deal 15% less, instead of 20% and 20%.', '{"stance:defensive_taken":0.7,"stance:defensive_dealt":0.85}');
insert into class_perk values ('blade_disarming_cut', 'blade', 5, 12, 'Disarming Cut', 'Spell, 12% of your stamina, 30 s before it can be called again. A blow at 70%; its next 3 blows within 30 s do 40% less damage.', '{}');
insert into class_perk values ('blade_measured_breathing', 'blade', 5, 31, 'Measured Breathing', 'Spell, 10% of your stamina, 60 s before it can be called again. For 20 s a swing or a draw costs no stamina.', '{}');
insert into class_perk values ('blade_guardian', 'blade', 5, 129, 'Guardian', 'With a shield in your off hand, 20% of the blows a creature lands on another person or a companion within 2 tiles of you land on your shield instead, and do nothing to them.', '{"cover:share":0.2}');
insert into class_perk values ('blade_last_stand', 'blade', 6, 28, 'Last Stand', 'Spell, 10 minutes before it can be called again. Costs no stamina. Only below 25% of your health: for 10 s you take 60% less damage.', '{}');
insert into class_perk values ('blade_guardians_call', 'blade', 6, 33, 'Guardian’s Call', 'Spell, 18% of your stamina, 45 s before it can be called again. Every creature within 5 tiles of you that is hunting somebody turns on you and hunts only you for 8 s.', '{}');
insert into class_perk values ('blade_shield_mastery', 'blade', 6, 109, 'Shield Mastery', 'Your shield blocks 8 percentage points more often, and the most it can block rises from 60% to 70%.', '{"block:shield":0.08,"blockcap:shield":0.7}');
insert into class_perk values ('berserker_wild_swing', 'berserker', 1, 18, 'Wild Swing', 'Spell, 5% of your stamina, 5 s before it can be called again. A blow at 140% that misses twice as often as a swing does.', '{}');
insert into class_perk values ('berserker_shrug_it_off', 'berserker', 1, 30, 'Shrug It Off', 'Spell, 10% of your stamina, 60 s before it can be called again. Your worst wound is 50% less severe, and it stops bleeding.', '{}');
insert into class_perk values ('berserker_axe_mastery', 'berserker', 1, 101, 'Axe Mastery', 'A blow with an axe does 10% more damage.', '{"dmg:axes":1.1}');
insert into class_perk values ('berserker_rending_chop', 'berserker', 2, 2, 'Rending Chop', 'Spell, 10% of your stamina, 12 s before it can be called again. With an axe in hand: a blow at 110% that bleeds it as a knife does, 15% of the blow a second for 6 s.', '{}');
insert into class_perk values ('berserker_skull_crack', 'berserker', 2, 3, 'Skull Crack', 'Spell, 12% of your stamina, 15 s before it can be called again. With a maul in hand: a blow at 120% that holds it where it stands, neither moving nor striking, for 2 s; a monster for 1 s.', '{}');
insert into class_perk values ('berserker_maul_mastery', 'berserker', 2, 106, 'Maul Mastery', 'A blow with a maul does 10% more damage.', '{"dmg:mauls":1.1}');
insert into class_perk values ('berserker_battle_rage', 'berserker', 3, 21, 'Battle Rage', 'Spell, 15% of your stamina, 90 s before it can be called again. For 15 s you deal 30% more damage and take 20% more.', '{}');
insert into class_perk values ('berserker_adrenaline', 'berserker', 3, 29, 'Adrenaline', 'Spell, 2 minutes before it can be called again. Costs no stamina. For 10 s a swing or a draw costs no stamina and takes 15% less time.', '{}');
insert into class_perk values ('berserker_executioner', 'berserker', 3, 125, 'Executioner', 'A blow on a creature below 25% of its health does 25% more damage.', '{"finish:below":0.25,"finish:dmg":1.25}');
insert into class_perk values ('berserker_execute', 'berserker', 4, 6, 'Execute', 'Spell, 15% of your stamina, 30 s before it can be called again. A blow at 300% on a creature below 25% of its health, and at 100% on one above it.', '{}');
insert into class_perk values ('berserker_blood_price', 'berserker', 4, 20, 'Blood Price', 'Spell, 30 s before it can be called again. Costs no stamina but 10% of your health: a blow at 250%.', '{}');
insert into class_perk values ('berserker_pain_fuels', 'berserker', 4, 112, 'Pain Fuels', 'Below 50% of your health you deal 15% more damage, and below 25% of it 30% more.', '{"pain:below":0.5,"pain:dmg":1.15,"pain:deep":0.25,"pain:deeper":1.3}');
insert into class_perk values ('berserker_overhead_smash', 'berserker', 5, 8, 'Overhead Smash', 'Spell, 15% of your stamina, 20 s before it can be called again. A crushing blow at 250% that cannot miss; your own next swing comes 1.5 s later.', '{}');
insert into class_perk values ('berserker_whirlwind', 'berserker', 5, 14, 'Whirlwind', 'Spell, 25% of your stamina, 45 s before it can be called again. Two blows at 90% on every enemy within 2 tiles of you.', '{}');
insert into class_perk values ('berserker_wild_strength', 'berserker', 5, 130, 'Wild Strength', 'A swing of a two-handed weapon takes 10% less time.', '{"swing:two_handed":0.9}');
insert into class_perk values ('berserker_earthshaker', 'berserker', 6, 45, 'Earthshaker', 'Spell, 25% of your stamina, 60 s before it can be called again. With a maul in hand: a blow at 100% on every enemy within 3 tiles of you, and each one held where it stands for 1 s.', '{}');
insert into class_perk values ('berserker_last_rage', 'berserker', 6, 50, 'Last Rage', 'Spell, 10 minutes before it can be called again. Costs no stamina. Only below 25% of your health: for 10 s every blow you land is critical.', '{}');
insert into class_perk values ('berserker_thirst_for_blood', 'berserker', 6, 113, 'Thirst for Blood', 'Every blow you land on a creature gives you back 1% of your health.', '{"leech:blow":0.01}');
insert into class_perk values ('pikeman_overreach', 'pikeman', 1, 13, 'Overreach', 'Spell, 8% of your stamina, 8 s before it can be called again. A blow at 110% on an enemy up to 2 tiles past your reach; your own next swing comes 1 s later.', '{}');
insert into class_perk values ('pikeman_warning_thrust', 'pikeman', 1, 38, 'Warning Thrust', 'Spell, 6% of your stamina, 10 s before it can be called again. A creature within your reach that is not fighting you will not come for you for 30 s, alone or with its pack, unless you strike it first.', '{}');
insert into class_perk values ('pikeman_scarred', 'pikeman', 1, 129, 'Scarred', 'A wound a blow opens on you starts 20% less severe, so it bleeds and slows you less; one already open deepens as it always did. What the blow takes off your health is the same.', '{"severity:new":0.8}');
insert into class_perk values ('pikeman_vital_thrust', 'pikeman', 2, 5, 'Vital Thrust', 'Spell, 12% of your stamina, 20 s before it can be called again. A blow at 120% that is critical twice as often as a swing is.', '{}');
insert into class_perk values ('pikeman_sweep_the_legs', 'pikeman', 2, 6, 'Sweep the Legs', 'Spell, 10% of your stamina, 15 s before it can be called again. A blow at 80%; for 8 s it walks, hunts and flees at 50% of its pace.', '{}');
insert into class_perk values ('pikeman_light_haft', 'pikeman', 2, 105, 'Light Haft', 'A swing of a polearm costs 25% less stamina.', '{"wind:polearms":0.75}');
insert into class_perk values ('pikeman_rally_the_line', 'pikeman', 3, 32, 'Rally the Line', 'Spell, 15% of your stamina, 90 s before it can be called again. You and everybody within 5 tiles of you get 20% of a full bar of stamina back.', '{}');
insert into class_perk values ('pikeman_hook', 'pikeman', 3, 33, 'Hook', 'Spell, 10% of your stamina, 15 s before it can be called again. An enemy up to 4 tiles off is dragged 2 tiles towards you, no nearer than 1 tile, over ground it could walk, and turns on you as if struck.', '{}');
insert into class_perk values ('pikeman_monster_hunter', 'pikeman', 3, 121, 'Monster Hunter', 'A blow or a shot that lands on a monster (a goblin, orc, ogre or dragon) does 15% more damage.', '{"monster:dmg":1.15}');
insert into class_perk values ('pikeman_twin_thrust', 'pikeman', 4, 14, 'Twin Thrust', 'Spell, 14% of your stamina, 20 s before it can be called again. Two blows at 70% each, one after the other.', '{}');
insert into class_perk values ('pikeman_reach_advantage', 'pikeman', 4, 19, 'Reach Advantage', 'Spell, 8% of your stamina, 15 s before it can be called again. A blow at 150% on a creature not yet within its own reach of you (1.1 tiles, or 6 for one that throws), and at 100% on one that is.', '{}');
insert into class_perk values ('pikeman_bastion', 'pikeman', 4, 113, 'Bastion', 'While your feet have not moved for 1.5 s, every blow that lands on you does 15% less damage.', '{"still:taken":0.85}');
insert into class_perk values ('pikeman_skewer', 'pikeman', 5, 2, 'Skewer', 'Spell, 12% of your stamina, 15 s before it can be called again. A blow at 150%, and one at 60% on every enemy up to 2 tiles behind it and within 0.5 tiles of the line of the thrust.', '{}');
insert into class_perk values ('pikeman_keep_away', 'pikeman', 5, 17, 'Keep Away', 'Spell, 10% of your stamina, 20 s before it can be called again. For 10 s every blow you land pushes what it lands on 1 tile further from you, over ground it could walk.', '{}');
insert into class_perk values ('pikeman_long_reach', 'pikeman', 5, 102, 'Long Reach', 'A polearm reaches 0.5 tiles further: a spear 3.7 tiles instead of 3.2.', '{"length:polearms":0.5}');
insert into class_perk values ('pikeman_brace_for_the_charge', 'pikeman', 6, 3, 'Brace for the Charge', 'Spell, 10% of your stamina, 20 s before it can be called again. For 6 s the first creature that comes at you from outside your reach is stopped at the edge of it by a blow at 200%, and its next blow is put back 2 s.', '{}');
insert into class_perk values ('pikeman_fend_off', 'pikeman', 6, 35, 'Fend Off', 'Spell, 10% of your stamina, 20 s before it can be called again. For 8 s anything that comes within 1.1 tiles of you to strike is pushed 2 tiles back instead, over ground it could walk.', '{}');
insert into class_perk values ('pikeman_reach_discipline', 'pikeman', 6, 118, 'Reach Discipline', 'A blow or a shot that lands on a creature inside your reach and not yet inside its own reach of you (1.1 tiles, or 6 for one that throws) does 20% more damage.', '{"gap:dmg":1.2}');
insert into class_perk values ('archer_aimed_shot', 'archer', 1, 1, 'Aimed Shot', 'Spell, 8% of your stamina, 8 s before it can be called again. With a bow in hand: a shot at 140% that cannot miss.', '{}');
insert into class_perk values ('archer_quick_shot', 'archer', 1, 2, 'Quick Shot', 'Spell, 6% of your stamina, 6 s before it can be called again. With a bow in hand: a shot at 80%; your own next draw comes 1 s sooner.', '{}');
insert into class_perk values ('archer_arrow_saver', 'archer', 1, 108, 'Arrow Saver', 'An arrow that lands on a creature comes back to your pack 1 in 4 times.', '{"save:arrow":0.25}');
insert into class_perk values ('archer_long_shot', 'archer', 2, 9, 'Long Shot', 'Spell, 10% of your stamina, 15 s before it can be called again. With a bow in hand: a shot at 110% on an enemy up to half again your bow''s range off, landing as often as one at the near end does.', '{}');
insert into class_perk values ('archer_read_the_wind', 'archer', 2, 29, 'Read the Wind', 'Spell, 6% of your stamina, 30 s before it can be called again. Your next shot within 30 s, a draw''s or a spell''s, cannot miss and is critical twice as often.', '{}');
insert into class_perk values ('archer_close_quarters', 'archer', 2, 107, 'Close Quarters', 'You can draw a bow on a creature 0.6 tiles off, instead of no nearer than 1.2.', '{"closest:draw":0.5}');
insert into class_perk values ('archer_crippling_shot', 'archer', 3, 6, 'Crippling Shot', 'Spell, 10% of your stamina, 15 s before it can be called again. With a bow in hand: a shot at 80%; for 8 s it walks, hunts and flees at 50% of its pace.', '{}');
insert into class_perk values ('archer_point_blank', 'archer', 3, 10, 'Point Blank', 'Spell, 8% of your stamina, 10 s before it can be called again. With a bow in hand: a shot at 160% on an enemy within 2 tiles of you, nearer than a draw can be made (1.2 tiles) as well.', '{}');
insert into class_perk values ('archer_ambush', 'archer', 3, 114, 'Ambush', 'A shot that lands on a creature that is not after you, one that has not noticed you or is after somebody else, does 50% more damage.', '{"ambush:dmg":1.5}');
insert into class_perk values ('archer_twin_arrows', 'archer', 4, 3, 'Twin Arrows', 'Spell, 14% of your stamina, 20 s before it can be called again. With a bow in hand: two arrows loosed at once, each a shot at 75%.', '{}');
insert into class_perk values ('archer_pinning_shot', 'archer', 4, 7, 'Pinning Shot', 'Spell, 14% of your stamina, 25 s before it can be called again. With a bow in hand: a shot at 90% that holds it where it stands, neither moving nor striking, for 2 s; a monster for 1 s.', '{}');
insert into class_perk values ('archer_mobile_archer', 'archer', 4, 124, 'Mobile Archer', 'While you draw a bow you walk at 80% of your pace, instead of 60%.', '{"pace:draw":0.8}');
insert into class_perk values ('archer_expose', 'archer', 5, 14, 'Expose', 'Spell, 15% of your stamina, 60 s before it can be called again. An enemy within 12 tiles: for 15 s every blow and shot a person lands on it does 15% more damage.', '{}');
insert into class_perk values ('archer_decoy', 'archer', 5, 25, 'Decoy', 'Spell, 12% of your stamina, 45 s before it can be called again. For 6 s every creature that strikes at you strikes a decoy at your feet instead, and nothing lands on you.', '{}');
insert into class_perk values ('archer_bow_mastery', 'archer', 5, 101, 'Bow Mastery', 'A shot does 10% more damage.', '{"dmg:archery":1.1}');
insert into class_perk values ('archer_snipe', 'archer', 6, 48, 'Snipe', 'Spell, 20% of your stamina, 60 s before it can be called again. With a bow in hand: a shot at 300% on a creature that is not after anybody.', '{}');
insert into class_perk values ('archer_deadeye', 'archer', 6, 49, 'Deadeye', 'Spell, 30% of your stamina, 5 minutes before it can be called again. For 10 s a draw takes 40% less time.', '{}');
insert into class_perk values ('archer_long_draw', 'archer', 6, 102, 'Long Draw', 'Your bow reaches 15% further: a short bow 6.9 tiles instead of 6, a composite bow 19.55 instead of 17.', '{"far:archery":1.15}');
insert into class_perk values ('skirmisher_snap_throw', 'skirmisher', 1, 2, 'Snap Throw', 'Spell, 5% of your stamina, 5 s before it can be called again. With a javelin or a throwing axe in hand: a throw at 80%; your own next swing comes 1 s sooner.', '{}');
insert into class_perk values ('skirmisher_long_throw', 'skirmisher', 1, 3, 'Long Throw', 'Spell, 10% of your stamina, 15 s before it can be called again. With a javelin or a throwing axe in hand: a throw at 110% on an enemy up to 2 tiles past your reach.', '{}');
insert into class_perk values ('skirmisher_light_throw', 'skirmisher', 1, 104, 'Light Throw', 'A swing of a javelin or a throwing axe costs 25% less stamina.', '{"wind:throwing":0.75}');
insert into class_perk values ('skirmisher_heavy_throw', 'skirmisher', 2, 7, 'Heavy Throw', 'Spell, 12% of your stamina, 20 s before it can be called again. With a javelin or a throwing axe in hand: a throw at 140% that staggers it as a maul does: a heavy blow knocked off its stroke, and its next blow put back 1 s.', '{}');
insert into class_perk values ('skirmisher_hit_and_run', 'skirmisher', 2, 31, 'Hit and Run', 'Spell, 12% of your stamina, 30 s before it can be called again. With a javelin, a throwing axe or a knife in hand: a throw or a knife blow at 100%, and for 5 s you walk 40% faster.', '{}');
insert into class_perk values ('skirmisher_keen_edge', 'skirmisher', 2, 107, 'Keen Edge', 'A blow of a javelin or a throwing axe that lands is critical 4 percentage points more often.', '{"crit:throwing":0.04}');
insert into class_perk values ('skirmisher_gut_throw', 'skirmisher', 3, 8, 'Gut Throw', 'Spell, 12% of your stamina, 20 s before it can be called again. With a javelin or a throwing axe in hand: a throw at 90% that bleeds it as a knife does, 15% of the throw a second for 6 s.', '{}');
insert into class_perk values ('skirmisher_parting_throw', 'skirmisher', 3, 12, 'Parting Throw', 'Spell, 10% of your stamina, 20 s before it can be called again. With a javelin or a throwing axe in hand: a throw at 100%, and you leap 3 tiles straight back from it, over ground you could walk.', '{}');
insert into class_perk values ('skirmisher_lethal', 'skirmisher', 3, 112, 'Lethal', 'A critical blow of a knife lands 2.25 times as hard, instead of 1.75.', '{"crithit:knives":2.25}');
insert into class_perk values ('skirmisher_double_throw', 'skirmisher', 4, 4, 'Double Throw', 'Spell, 14% of your stamina, 20 s before it can be called again. With a javelin or a throwing axe in hand: two throws at 70% each, one after the other.', '{}');
insert into class_perk values ('skirmisher_ricochet', 'skirmisher', 4, 9, 'Ricochet', 'Spell, 15% of your stamina, 25 s before it can be called again. With a javelin or a throwing axe in hand: a throw at 100% that, when it lands, glances on to the nearest other enemy within 3 tiles of it at 60%.', '{}');
insert into class_perk values ('skirmisher_long_bleed', 'skirmisher', 4, 110, 'Long Bleed', 'Every bleed you open lasts 9 s instead of 6 s: a knife’s, a broadhead arrow’s and a Gut Throw’s.', '{"bleed:secs":1.5}');
insert into class_perk values ('skirmisher_fade', 'skirmisher', 5, 36, 'Fade', 'Spell, 10% of your stamina, 45 s before it can be called again. Every creature hunting you loses you, and will not come for you again for 10 s unless you strike it.', '{}');
insert into class_perk values ('skirmisher_opportunist', 'skirmisher', 5, 44, 'Opportunist', 'Spell, 10% of your stamina, 30 s before it can be called again. For 10 s every blow, throw and shot of yours on a creature fighting somebody else does 30% more damage.', '{}');
insert into class_perk values ('skirmisher_riposte', 'skirmisher', 5, 120, 'Riposte', 'Every creature’s blow you dodge is answered with a blow at 50% of a swing’s from what you hold, when it is within your reach.', '{"riposte:blow":0.5}');
insert into class_perk values ('skirmisher_fan_of_blades', 'skirmisher', 6, 10, 'Fan of Blades', 'Spell, 22% of your stamina, 45 s before it can be called again. With a javelin or a throwing axe in hand: a throw at 60% at the enemy you aim at and at every other enemy within 3 tiles of it.', '{}');
insert into class_perk values ('skirmisher_marked_for_death', 'skirmisher', 6, 49, 'Marked for Death', 'Spell, 15% of your stamina, 60 s before it can be called again. An enemy within 12 tiles: for 15 s every blow, throw and shot a person lands on it is critical twice as often.', '{}');
insert into class_perk values ('skirmisher_long_arm', 'skirmisher', 6, 102, 'Long Arm', 'A javelin or a throwing axe reaches 1 tile further: a throwing axe 5.2 tiles instead of 4.2, a javelin 6.2 tiles instead of 5.2.', '{"length:throwing":1}');
insert into class_perk values ('chirurgeon_field_dressing', 'chirurgeon', 1, 1, 'Field Dressing', 'Spell, 6% of your stamina, 8 s before it can be called again. You or somebody within 2 tiles of you gets 10% of their health back, and their worst bleeding wound stops bleeding.', '{}');
insert into class_perk values ('chirurgeon_quick_stitch', 'chirurgeon', 1, 2, 'Quick Stitch', 'Spell, 8% of your stamina, 10 s before it can be called again. The worst wound on you or on somebody within 2 tiles of you closes by 30% of its severity.', '{}');
insert into class_perk values ('chirurgeon_field_surgeon', 'chirurgeon', 1, 101, 'Field Surgeon', 'You can dress the wounds of somebody standing beside you, at your first aid and with your dressings, as a Naturalist’s Field Medic can.', '{"dress_others":1}');
insert into class_perk values ('chirurgeon_regenerate', 'chirurgeon', 2, 4, 'Regenerate', 'Spell, 15% of your stamina, 45 s before it can be called again. You or somebody within 4 tiles of you gets 2% of their health back a second for 15 s.', '{}');
insert into class_perk values ('chirurgeon_leech', 'chirurgeon', 2, 49, 'Leech', 'Spell, 12% of your stamina, 20 s before it can be called again. With a knife in hand: a knife blow at 80%, and you get back as large a share of your health as it takes of the creature''s.', '{}');
insert into class_perk values ('chirurgeon_quick_bandage', 'chirurgeon', 2, 105, 'Quick Bandage', 'A dressing takes 30% less time: 4.9 s instead of 7 s.', '{"time:bind_wound":0.7}');
insert into class_perk values ('chirurgeon_surgeons_hands', 'chirurgeon', 3, 17, 'Surgeon’s Hands', 'Spell, 12% of your stamina, 60 s before it can be called again. For 20 s every dressing you put on puts back twice as much health.', '{}');
insert into class_perk values ('chirurgeon_toxin', 'chirurgeon', 3, 43, 'Toxin', 'Spell, 12% of your stamina, 30 s before it can be called again. An enemy within 4 tiles of you bleeds 1% of its full health a second for 20 s; a bleed never takes the last of it.', '{}');
insert into class_perk values ('chirurgeon_clean_cloth', 'chirurgeon', 3, 104, 'Clean Cloth', 'A wound you dress goes bad half as often while your dressing is on it, whoever''s it is.', '{"fester:bind_wound":0.5}');
insert into class_perk values ('chirurgeon_healing_circle', 'chirurgeon', 4, 6, 'Healing Circle', 'Spell, 25% of your stamina, 60 s before it can be called again. You and everybody within 4 tiles of you get 15% of your health back.', '{}');
insert into class_perk values ('chirurgeon_mass_dressing', 'chirurgeon', 4, 19, 'Mass Dressing', 'Spell, 25% of your stamina, 60 s before it can be called again. On you and everybody within 3 tiles of you, the worst wound stops bleeding and closes by 20% of its severity.', '{}');
insert into class_perk values ('chirurgeon_bedside_manner', 'chirurgeon', 4, 122, 'Bedside Manner', 'A dressing you put on gives whoever it is on 10% of their stamina back.', '{"stamina:bind_wound":0.1}');
insert into class_perk values ('chirurgeon_battlefield_surgery', 'chirurgeon', 5, 15, 'Battlefield Surgery', 'Spell, 30% of your stamina, 2 minutes before it can be called again. Every wound on you or on somebody within 2 tiles of you closes by 50% of its severity, and they get 20% of their health back.', '{}');
insert into class_perk values ('chirurgeon_plague', 'chirurgeon', 5, 46, 'Plague', 'Spell, 20% of your stamina, 60 s before it can be called again. Every enemy within 4 tiles of you bleeds 1% of its full health a second for 10 s; a bleed never takes the last of it.', '{}');
insert into class_perk values ('chirurgeon_sure_dressing', 'chirurgeon', 5, 106, 'Sure Dressing', 'A dressing of yours never slips (now a check at difficulty 10).', '{"fail:bind_wound":0}');
insert into class_perk values ('chirurgeon_miracle_worker', 'chirurgeon', 6, 20, 'Miracle Worker', 'Spell, 40% of your stamina, 10 minutes before it can be called again. Every wound on you or on somebody within 4 tiles of you closes, with whatever bleeding and venom was in it, and they get 50% of their health back.', '{}');
insert into class_perk values ('chirurgeon_restoration', 'chirurgeon', 6, 50, 'Restoration', 'Spell, 30% of your stamina, 5 minutes before it can be called again. Every wound on you closes, and you get 30% of your health back.', '{}');
insert into class_perk values ('chirurgeon_triage_instinct', 'chirurgeon', 6, 123, 'Triage Instinct', 'A dressing on somebody below 30% of their health puts back 50% more health.', '{"triage:below":0.3,"triage:heal":1.5}');
insert into class_perk values ('beastmaster_sic', 'beastmaster', 1, 1, 'Sic', 'Spell, 5% of your stamina, 6 s before it can be called again. With a companion following you: your companion strikes an enemy within its reach (0.9 tiles of it) at once, a blow at 130% of its own.', '{}');
insert into class_perk values ('beastmaster_lick_wounds', 'beastmaster', 1, 15, 'Lick Wounds', 'Spell, 6% of your stamina, 15 s before it can be called again. With a companion following you: your companion gets 15% of its health back.', '{}');
insert into class_perk values ('beastmaster_fleet', 'beastmaster', 1, 106, 'Fleet', 'Your companion runs 30% faster.', '{"kept:speed":1.3}');
insert into class_perk values ('beastmaster_pounce', 'beastmaster', 2, 2, 'Pounce', 'Spell, 8% of your stamina, 12 s before it can be called again. With a companion following you: your companion leaps onto an enemy up to 5 tiles from it, over ground it could run, and strikes it at 100% of its own blow; the enemy''s next blow is put back 0.5 s.', '{}');
insert into class_perk values ('beastmaster_snarl', 'beastmaster', 2, 28, 'Snarl', 'Spell, 8% of your stamina, 15 s before it can be called again. With a companion following you: every wild creature within 4 tiles of your companion turns on it.', '{}');
insert into class_perk values ('beastmaster_long_leash', 'beastmaster', 2, 120, 'Long Leash', 'Your companion keeps up a fight up to 14 tiles from you instead of 9, and, guarding you or aggressive, goes for a creature up to 8 tiles from you instead of 5.', '{"leash:companion":14,"sight:companion":8}');
insert into class_perk values ('beastmaster_drag_down', 'beastmaster', 3, 8, 'Drag Down', 'Spell, 15% of your stamina, 40 s before it can be called again. With a companion following you: your companion strikes an enemy within its reach at 50% of its own blow, and holds it where it stands, neither moving nor striking, for 4 s.', '{}');
insert into class_perk values ('beastmaster_guard_me', 'beastmaster', 3, 27, 'Guard Me', 'Spell, 10% of your stamina, 30 s before it can be called again. With a companion following you: your companion leaps to your side, and every creature within 6 tiles of you that is hunting you turns on it.', '{}');
insert into class_perk values ('beastmaster_thick_hide', 'beastmaster', 3, 101, 'Thick Hide', 'Your companion has 20% more health.', '{"kept:hardy":1.2}');
insert into class_perk values ('beastmaster_disembowel', 'beastmaster', 4, 13, 'Disembowel', 'Spell, 18% of your stamina, 60 s before it can be called again. With a companion following you: your companion strikes an enemy within its reach at 100% of its own blow, and the enemy bleeds 30% of the blow a second for 8 s; a bleed never takes the last of it.', '{}');
insert into class_perk values ('beastmaster_bloodlust', 'beastmaster', 4, 18, 'Bloodlust', 'Spell, 15% of your stamina, 60 s before it can be called again. With a companion following you: for 15 s your companion''s blows are 40% larger.', '{}');
insert into class_perk values ('beastmaster_hardy_stock', 'beastmaster', 4, 102, 'Hardy Stock', 'Your companion takes 15% less from every blow.', '{"kept:soak":0.85}');
insert into class_perk values ('beastmaster_vengeance', 'beastmaster', 5, 32, 'Vengeance', 'Spell, 15% of your stamina, 90 s before it can be called again. With a companion following you: for 20 s, every creature that lands a blow on you is struck back by your companion at 60% of its own blow, when it is within 5 tiles of it.', '{}');
insert into class_perk values ('beastmaster_feral_bond', 'beastmaster', 5, 50, 'Feral Bond', 'Spell, 25% of your stamina, 10 minutes before it can be called again. With a companion following you: for 30 s every blow that lands on you or on your companion is split between you, 50% to each.', '{}');
insert into class_perk values ('beastmaster_quick_paws', 'beastmaster', 5, 108, 'Quick Paws', 'Your companion strikes 15% more often: every 1.04 s instead of every 1.2 s.', '{"kept:haste":1.15}');
insert into class_perk values ('beastmaster_call_of_the_wild', 'beastmaster', 6, 41, 'Call of the Wild', 'Spell, 40% of your stamina, 15 minutes before it can be called again. A wild creature within 4 tiles of you whose tame level is no more than your taming is tamed outright, as a tame that takes: it follows you, or goes into an empty creature crate in your pack if something follows you already. Never a monster.', '{}');
insert into class_perk values ('beastmaster_primal_fury', 'beastmaster', 6, 48, 'Primal Fury', 'Spell, 30% of your stamina, 5 minutes before it can be called again. With a companion following you: for 20 s your companion''s blows are 75% larger and come 50% more often.', '{}');
insert into class_perk values ('beastmaster_shared_wounds', 'beastmaster', 6, 119, 'Shared Wounds', 'While your companion is within 4 tiles of you, it takes 20% of every blow that lands on you instead of you.', '{"bond:share":0.2,"bond:reach":4}');
