insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('blade_measured_cut', 'blade', 1, 'Measured Cut', 'A blow at 130% that cannot miss, on an enemy within your reach.', 0.08, 6, array['enemy']::text[], '{"more":1.3}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('blade_challenge', 'blade', 32, 'Challenge', 'The creature turns on you at once and hunts only you for 10 s.', 0.08, 15, array['enemy']::text[], '{"secs":10}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('blade_lunge', 'blade', 2, 'Lunge', 'You stride to an enemy up to 4 tiles off, over ground you could walk, and strike it at 150%.', 0.1, 10, array['enemy']::text[], '{"reach":4,"more":1.5}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('blade_hamstring', 'blade', 11, 'Hamstring', 'A blow at 80%; for 10 s it walks, hunts and flees at 50% of its pace.', 0.1, 20, array['enemy']::text[], '{"more":0.8,"pace":0.5,"secs":10}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('blade_shield_bash', 'blade', 15, 'Shield Bash', 'With a shield in your off hand: a crushing blow at 70% that knocks a heavy blow off its stroke and puts its next blow back 2 s.', 0.1, 12, array['enemy']::text[], '{"more":0.7,"back":2}', 'shield');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('blade_second_breath', 'blade', 29, 'Second Breath', 'Costs no stamina. 40% of a full bar of stamina back at once.', 0, 180, array['self']::text[], '{"stamina":0.4}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('blade_deflect', 'blade', 19, 'Deflect', 'For 6 s, every blow you block lands back on what struck at 50% of the blow.', 0.1, 25, array['self']::text[], '{"share":0.5,"secs":6}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('blade_hold_the_line', 'blade', 26, 'Hold the Line', 'For 15 s your wounds bleed 50% less, and those on your arms do not slow your swing.', 0.15, 90, array['self']::text[], '{"bleed":0.5,"secs":15}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('blade_disarming_cut', 'blade', 12, 'Disarming Cut', 'A blow at 70%; its next 3 blows within 30 s do 40% less damage.', 0.12, 30, array['enemy']::text[], '{"more":0.7,"cut":0.4,"blows":3,"secs":30}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('blade_measured_breathing', 'blade', 31, 'Measured Breathing', 'For 20 s a swing or a draw costs no stamina.', 0.1, 60, array['self']::text[], '{"secs":20}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('blade_guardians_call', 'blade', 33, 'Guardian’s Call', 'Every creature within 5 tiles of you that is hunting somebody turns on you and hunts only you for 8 s.', 0.18, 45, array['self']::text[], '{"reach":5,"secs":8}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('blade_last_stand', 'blade', 28, 'Last Stand', 'Costs no stamina. Only below 25% of your health: for 10 s you take 60% less damage.', 0, 600, array['self']::text[], '{"below":0.25,"cut":0.6,"secs":10}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('berserker_wild_swing', 'berserker', 18, 'Wild Swing', 'A blow at 140% that misses twice as often as a swing does.', 0.05, 5, array['enemy']::text[], '{"more":1.4,"miss":2}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('berserker_shrug_it_off', 'berserker', 30, 'Shrug It Off', 'Your worst wound is 50% less severe, and it stops bleeding.', 0.1, 60, array['self']::text[], '{"severity":0.5}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('berserker_rending_chop', 'berserker', 2, 'Rending Chop', 'With an axe in hand: a blow at 110% that bleeds it as a knife does, 15% of the blow a second for 6 s.', 0.1, 12, array['enemy']::text[], '{"more":1.1}', 'axes');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('berserker_skull_crack', 'berserker', 3, 'Skull Crack', 'With a maul in hand: a blow at 120% that holds it where it stands, neither moving nor striking, for 2 s; a monster for 1 s.', 0.12, 15, array['enemy']::text[], '{"more":1.2,"hold":2,"monster":0.5}', 'mauls');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('berserker_battle_rage', 'berserker', 21, 'Battle Rage', 'For 15 s you deal 30% more damage and take 20% more.', 0.15, 90, array['self']::text[], '{"dealt":1.3,"taken":1.2,"secs":15}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('berserker_adrenaline', 'berserker', 29, 'Adrenaline', 'Costs no stamina. For 10 s a swing or a draw costs no stamina and takes 15% less time.', 0, 120, array['self']::text[], '{"time":0.85,"secs":10}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('berserker_blood_price', 'berserker', 20, 'Blood Price', 'Costs no stamina but 10% of your health: a blow at 250%.', 0, 30, array['enemy']::text[], '{"health":0.1,"more":2.5}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('berserker_execute', 'berserker', 6, 'Execute', 'A blow at 300% on a creature below 25% of its health, and at 100% on one above it.', 0.15, 30, array['enemy']::text[], '{"low":0.25,"more":3,"whole":1}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('berserker_overhead_smash', 'berserker', 8, 'Overhead Smash', 'A crushing blow at 250% that cannot miss; your own next swing comes 1.5 s later.', 0.15, 20, array['enemy']::text[], '{"more":2.5,"wind":1.5}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('berserker_whirlwind', 'berserker', 14, 'Whirlwind', 'Two blows at 90% on every enemy within 2 tiles of you.', 0.25, 45, array['self']::text[], '{"more":0.9,"blows":2,"reach":2}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('berserker_earthshaker', 'berserker', 45, 'Earthshaker', 'With a maul in hand: a blow at 100% on every enemy within 3 tiles of you, and each one held where it stands for 1 s.', 0.25, 60, array['self']::text[], '{"more":1,"reach":3,"hold":1}', 'mauls');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('berserker_last_rage', 'berserker', 50, 'Last Rage', 'Costs no stamina. Only below 25% of your health: for 10 s every blow you land is critical.', 0, 600, array['self']::text[], '{"below":0.25,"secs":10}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('pikeman_warning_thrust', 'pikeman', 38, 'Warning Thrust', 'A creature within your reach that is not fighting you will not come for you for 30 s, alone or with its pack, unless you strike it first.', 0.06, 10, array['enemy']::text[], '{"secs":30}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('pikeman_overreach', 'pikeman', 13, 'Overreach', 'A blow at 110% on an enemy up to 2 tiles past your reach; your own next swing comes 1 s later.', 0.08, 8, array['enemy']::text[], '{"more":1.1,"past":2,"wind":1}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('pikeman_sweep_the_legs', 'pikeman', 6, 'Sweep the Legs', 'A blow at 80%; for 8 s it walks, hunts and flees at 50% of its pace.', 0.1, 15, array['enemy']::text[], '{"more":0.8,"pace":0.5,"secs":8}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('pikeman_vital_thrust', 'pikeman', 5, 'Vital Thrust', 'A blow at 120% that is critical twice as often as a swing is.', 0.12, 20, array['enemy']::text[], '{"more":1.2,"crit":2}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('pikeman_hook', 'pikeman', 33, 'Hook', 'An enemy up to 4 tiles off is dragged 2 tiles towards you, no nearer than 1 tile, over ground it could walk, and turns on you as if struck.', 0.1, 15, array['enemy']::text[], '{"reach":4,"pull":2,"least":1}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('pikeman_rally_the_line', 'pikeman', 32, 'Rally the Line', 'You and everybody within 5 tiles of you get 20% of a full bar of stamina back.', 0.15, 90, array['self']::text[], '{"reach":5,"stamina":0.2}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('pikeman_twin_thrust', 'pikeman', 14, 'Twin Thrust', 'Two blows at 70% each, one after the other.', 0.14, 20, array['enemy']::text[], '{"more":0.7,"blows":2}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('pikeman_reach_advantage', 'pikeman', 19, 'Reach Advantage', 'A blow at 150% on a creature not yet within its own reach of you (1.1 tiles, or 6 for one that throws), and at 100% on one that is.', 0.08, 15, array['enemy']::text[], '{"more":1.5,"whole":1}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('pikeman_skewer', 'pikeman', 2, 'Skewer', 'A blow at 150%, and one at 60% on every enemy up to 2 tiles behind it and within 0.5 tiles of the line of the thrust.', 0.12, 15, array['enemy']::text[], '{"more":1.5,"behind":2,"width":0.5,"through":0.6}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('pikeman_keep_away', 'pikeman', 17, 'Keep Away', 'For 10 s every blow you land pushes what it lands on 1 tile further from you, over ground it could walk.', 0.1, 20, array['self']::text[], '{"secs":10,"push":1}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('pikeman_fend_off', 'pikeman', 35, 'Fend Off', 'For 8 s anything that comes within 1.1 tiles of you to strike is pushed 2 tiles back instead, over ground it could walk.', 0.1, 20, array['self']::text[], '{"secs":8,"push":2}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('pikeman_brace_for_the_charge', 'pikeman', 3, 'Brace for the Charge', 'For 6 s the first creature that comes at you from outside your reach is stopped at the edge of it by a blow at 200%, and its next blow is put back 2 s.', 0.1, 20, array['self']::text[], '{"secs":6,"more":2,"back":2}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('archer_quick_shot', 'archer', 2, 'Quick Shot', 'With a bow in hand: a shot at 80%; your own next draw comes 1 s sooner.', 0.06, 6, array['enemy']::text[], '{"more":0.8,"sooner":1}', 'archery');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('archer_aimed_shot', 'archer', 1, 'Aimed Shot', 'With a bow in hand: a shot at 140% that cannot miss.', 0.08, 8, array['enemy']::text[], '{"more":1.4}', 'archery');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('archer_read_the_wind', 'archer', 29, 'Read the Wind', 'Your next shot within 30 s, a draw''s or a spell''s, cannot miss and is critical twice as often.', 0.06, 30, array['self']::text[], '{"secs":30,"crit":2}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('archer_long_shot', 'archer', 9, 'Long Shot', 'With a bow in hand: a shot at 110% on an enemy up to half again your bow''s range off, landing as often as one at the near end does.', 0.1, 15, array['enemy']::text[], '{"more":1.1,"range":1.5}', 'archery');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('archer_crippling_shot', 'archer', 6, 'Crippling Shot', 'With a bow in hand: a shot at 80%; for 8 s it walks, hunts and flees at 50% of its pace.', 0.1, 15, array['enemy']::text[], '{"more":0.8,"pace":0.5,"secs":8}', 'archery');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('archer_point_blank', 'archer', 10, 'Point Blank', 'With a bow in hand: a shot at 160% on an enemy within 2 tiles of you, nearer than a draw can be made (1.2 tiles) as well.', 0.08, 10, array['enemy']::text[], '{"more":1.6,"reach":2}', 'archery');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('archer_twin_arrows', 'archer', 3, 'Twin Arrows', 'With a bow in hand: two arrows loosed at once, each a shot at 75%.', 0.14, 20, array['enemy']::text[], '{"more":0.75,"arrows":2}', 'archery');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('archer_pinning_shot', 'archer', 7, 'Pinning Shot', 'With a bow in hand: a shot at 90% that holds it where it stands, neither moving nor striking, for 2 s; a monster for 1 s.', 0.14, 25, array['enemy']::text[], '{"more":0.9,"hold":2,"monster":0.5}', 'archery');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('archer_expose', 'archer', 14, 'Expose', 'An enemy within 12 tiles: for 15 s every blow and shot a person lands on it does 15% more damage.', 0.15, 60, array['enemy']::text[], '{"more":1.15,"secs":15}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('archer_decoy', 'archer', 25, 'Decoy', 'For 6 s every creature that strikes at you strikes a decoy at your feet instead, and nothing lands on you.', 0.12, 45, array['self']::text[], '{"secs":6}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('archer_snipe', 'archer', 48, 'Snipe', 'With a bow in hand: a shot at 300% on a creature that is not after anybody.', 0.2, 60, array['enemy']::text[], '{"more":3}', 'archery');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('archer_deadeye', 'archer', 49, 'Deadeye', 'For 10 s a draw takes 40% less time.', 0.3, 300, array['self']::text[], '{"time":0.6,"secs":10}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('skirmisher_snap_throw', 'skirmisher', 2, 'Snap Throw', 'With a javelin or a throwing axe in hand: a throw at 80%; your own next swing comes 1 s sooner.', 0.05, 5, array['enemy']::text[], '{"more":0.8,"sooner":1}', 'throwing');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('skirmisher_long_throw', 'skirmisher', 3, 'Long Throw', 'With a javelin or a throwing axe in hand: a throw at 110% on an enemy up to 2 tiles past your reach.', 0.1, 15, array['enemy']::text[], '{"more":1.1,"past":2}', 'throwing');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('skirmisher_hit_and_run', 'skirmisher', 31, 'Hit and Run', 'With a javelin, a throwing axe or a knife in hand: a throw or a knife blow at 100%, and for 5 s you walk 40% faster.', 0.12, 30, array['enemy']::text[], '{"more":1,"pace":1.4,"secs":5}', 'skirmish');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('skirmisher_heavy_throw', 'skirmisher', 7, 'Heavy Throw', 'With a javelin or a throwing axe in hand: a throw at 140% that staggers it as a maul does: a heavy blow knocked off its stroke, and its next blow put back 1 s.', 0.12, 20, array['enemy']::text[], '{"more":1.4}', 'throwing');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('skirmisher_gut_throw', 'skirmisher', 8, 'Gut Throw', 'With a javelin or a throwing axe in hand: a throw at 90% that bleeds it as a knife does, 15% of the throw a second for 6 s.', 0.12, 20, array['enemy']::text[], '{"more":0.9}', 'throwing');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('skirmisher_parting_throw', 'skirmisher', 12, 'Parting Throw', 'With a javelin or a throwing axe in hand: a throw at 100%, and you leap 3 tiles straight back from it, over ground you could walk.', 0.1, 20, array['enemy']::text[], '{"more":1,"leap":3}', 'throwing');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('skirmisher_double_throw', 'skirmisher', 4, 'Double Throw', 'With a javelin or a throwing axe in hand: two throws at 70% each, one after the other.', 0.14, 20, array['enemy']::text[], '{"more":0.7,"throws":2}', 'throwing');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('skirmisher_ricochet', 'skirmisher', 9, 'Ricochet', 'With a javelin or a throwing axe in hand: a throw at 100% that, when it lands, glances on to the nearest other enemy within 3 tiles of it at 60%.', 0.15, 25, array['enemy']::text[], '{"more":1,"reach":3,"glance":0.6}', 'throwing');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('skirmisher_opportunist', 'skirmisher', 44, 'Opportunist', 'For 10 s every blow, throw and shot of yours on a creature fighting somebody else does 30% more damage.', 0.1, 30, array['self']::text[], '{"more":1.3,"secs":10}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('skirmisher_fade', 'skirmisher', 36, 'Fade', 'Every creature hunting you loses you, and will not come for you again for 10 s unless you strike it.', 0.1, 45, array['self']::text[], '{"secs":10}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('skirmisher_fan_of_blades', 'skirmisher', 10, 'Fan of Blades', 'With a javelin or a throwing axe in hand: a throw at 60% at the enemy you aim at and at every other enemy within 3 tiles of it.', 0.22, 45, array['enemy']::text[], '{"more":0.6,"reach":3}', 'throwing');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('skirmisher_marked_for_death', 'skirmisher', 49, 'Marked for Death', 'An enemy within 12 tiles: for 15 s every blow, throw and shot a person lands on it is critical twice as often.', 0.15, 60, array['enemy']::text[], '{"crit":2,"secs":15}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('chirurgeon_field_dressing', 'chirurgeon', 1, 'Field Dressing', 'You or somebody within 2 tiles of you gets 10% of their health back, and their worst bleeding wound stops bleeding.', 0.06, 8, array['self', 'player']::text[], '{"heal":0.1,"reach":2}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('chirurgeon_quick_stitch', 'chirurgeon', 2, 'Quick Stitch', 'The worst wound on you or on somebody within 2 tiles of you closes by 30% of its severity.', 0.08, 10, array['self', 'player']::text[], '{"close":0.3,"reach":2}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('chirurgeon_leech', 'chirurgeon', 49, 'Leech', 'With a knife in hand: a knife blow at 80%, and you get back as large a share of your health as it takes of the creature''s.', 0.12, 20, array['enemy']::text[], '{"more":0.8}', 'knives');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('chirurgeon_regenerate', 'chirurgeon', 4, 'Regenerate', 'You or somebody within 4 tiles of you gets 2% of their health back a second for 15 s.', 0.15, 45, array['self', 'player']::text[], '{"each":0.02,"secs":15,"reach":4}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('chirurgeon_toxin', 'chirurgeon', 43, 'Toxin', 'An enemy within 4 tiles of you bleeds 1% of its full health a second for 20 s; a bleed never takes the last of it.', 0.12, 30, array['enemy']::text[], '{"each":0.01,"secs":20,"reach":4}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('chirurgeon_surgeons_hands', 'chirurgeon', 17, 'Surgeon’s Hands', 'For 20 s every dressing you put on puts back twice as much health.', 0.12, 60, array['self']::text[], '{"more":2,"secs":20}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('chirurgeon_healing_circle', 'chirurgeon', 6, 'Healing Circle', 'You and everybody within 4 tiles of you get 15% of your health back.', 0.25, 60, array['self']::text[], '{"heal":0.15,"reach":4}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('chirurgeon_mass_dressing', 'chirurgeon', 19, 'Mass Dressing', 'On you and everybody within 3 tiles of you, the worst wound stops bleeding and closes by 20% of its severity.', 0.25, 60, array['self']::text[], '{"close":0.2,"reach":3}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('chirurgeon_plague', 'chirurgeon', 46, 'Plague', 'Every enemy within 4 tiles of you bleeds 1% of its full health a second for 10 s; a bleed never takes the last of it.', 0.2, 60, array['self']::text[], '{"each":0.01,"secs":10,"reach":4}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('chirurgeon_battlefield_surgery', 'chirurgeon', 15, 'Battlefield Surgery', 'Every wound on you or on somebody within 2 tiles of you closes by 50% of its severity, and they get 20% of their health back.', 0.3, 120, array['self', 'player']::text[], '{"close":0.5,"heal":0.2,"reach":2}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('chirurgeon_restoration', 'chirurgeon', 50, 'Restoration', 'Every wound on you closes, and you get 30% of your health back.', 0.3, 300, array['self']::text[], '{"heal":0.3}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('chirurgeon_miracle_worker', 'chirurgeon', 20, 'Miracle Worker', 'Every wound on you or on somebody within 4 tiles of you closes, with whatever bleeding and venom was in it, and they get 50% of their health back.', 0.4, 600, array['self', 'player']::text[], '{"heal":0.5,"reach":4}', null);
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('beastmaster_sic', 'beastmaster', 1, 'Sic', 'With a companion following you: your companion strikes an enemy within its reach (0.9 tiles of it) at once, a blow at 130% of its own.', 0.05, 6, array['enemy']::text[], '{"more":1.3}', 'companion');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('beastmaster_lick_wounds', 'beastmaster', 15, 'Lick Wounds', 'With a companion following you: your companion gets 15% of its health back.', 0.06, 15, array['self']::text[], '{"heal":0.15}', 'companion');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('beastmaster_pounce', 'beastmaster', 2, 'Pounce', 'With a companion following you: your companion leaps onto an enemy up to 5 tiles from it, over ground it could run, and strikes it at 100% of its own blow; the enemy''s next blow is put back 0.5 s.', 0.08, 12, array['enemy']::text[], '{"reach":5,"more":1,"back":0.5}', 'companion');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('beastmaster_snarl', 'beastmaster', 28, 'Snarl', 'With a companion following you: every wild creature within 4 tiles of your companion turns on it.', 0.08, 15, array['self']::text[], '{"reach":4}', 'companion');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('beastmaster_guard_me', 'beastmaster', 27, 'Guard Me', 'With a companion following you: your companion leaps to your side, and every creature within 6 tiles of you that is hunting you turns on it.', 0.1, 30, array['self']::text[], '{"reach":6}', 'companion');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('beastmaster_drag_down', 'beastmaster', 8, 'Drag Down', 'With a companion following you: your companion strikes an enemy within its reach at 50% of its own blow, and holds it where it stands, neither moving nor striking, for 4 s.', 0.15, 40, array['enemy']::text[], '{"more":0.5,"hold":4}', 'companion');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('beastmaster_disembowel', 'beastmaster', 13, 'Disembowel', 'With a companion following you: your companion strikes an enemy within its reach at 100% of its own blow, and the enemy bleeds 30% of the blow a second for 8 s; a bleed never takes the last of it.', 0.18, 60, array['enemy']::text[], '{"more":1,"each":0.3,"secs":8}', 'companion');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('beastmaster_bloodlust', 'beastmaster', 18, 'Bloodlust', 'With a companion following you: for 15 s your companion''s blows are 40% larger.', 0.15, 60, array['self']::text[], '{"more":1.4,"secs":15}', 'companion');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('beastmaster_vengeance', 'beastmaster', 32, 'Vengeance', 'With a companion following you: for 20 s, every creature that lands a blow on you is struck back by your companion at 60% of its own blow, when it is within 5 tiles of it.', 0.15, 90, array['self']::text[], '{"more":0.6,"reach":5,"secs":20}', 'companion');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('beastmaster_feral_bond', 'beastmaster', 50, 'Feral Bond', 'With a companion following you: for 30 s every blow that lands on you or on your companion is split between you, 50% to each.', 0.25, 600, array['self']::text[], '{"share":0.5,"secs":30}', 'companion');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('beastmaster_primal_fury', 'beastmaster', 48, 'Primal Fury', 'With a companion following you: for 20 s your companion''s blows are 75% larger and come 50% more often.', 0.3, 300, array['self']::text[], '{"more":1.75,"quick":1.5,"secs":20}', 'companion');
insert into class_spell (id, class, num, name, note, cost, rest, on_what, fx, needs) values ('beastmaster_call_of_the_wild', 'beastmaster', 41, 'Call of the Wild', 'A wild creature within 4 tiles of you whose tame level is no more than your taming is tamed outright, as a tame that takes: it follows you, or goes into an empty creature crate in your pack if something follows you already. Never a monster.', 0.4, 900, array['enemy']::text[], '{"reach":4}', null);
