insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('blessing_soothe', 'blessing', 1, 'Soothe', 'Heals 10% of their health and stops their worst bleeding wound bleeding.', 8, 20, array['self', 'player']::text[], null, '{"heal":0.1}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('blessing_ward', 'blessing', 1, 'Ward', 'The next blow to land on them within 30 s does 50% less damage.', 10, 60, array['self', 'player']::text[], null, '{"cut":0.5,"secs":30}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('blessing_tend', 'blessing', 1, 'Tend', 'Heals the wildermon 25% of its health and stops it bleeding.', 8, 30, array['wildermon']::text[], null, '{"heal":0.25}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('blessing_purify', 'blessing', 2, 'Purify', 'Draws the venom out of every wound they have and closes every burn.', 12, 45, array['self', 'player']::text[], null, '{}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('blessing_calm', 'blessing', 2, 'Calm', 'A wild creature stops hunting and cannot start a hunt for 60 s. Monsters are not calmed.', 14, 90, array['enemy']::text[], null, '{"secs":60}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('blessing_steady', 'blessing', 2, 'Steady Hands', 'For 30 minutes, every job that wants this tool takes 10% less time while you carry it.', 14, 600, array['object']::text[], null, '{"cut":0.1,"secs":1800}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('blessing_renewal', 'blessing', 3, 'Renewal', 'Heals 3% of their health every 3 s for 30 s: 30% in all.', 20, 60, array['self', 'player']::text[], null, '{"each":0.03,"every":3,"secs":30}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('blessing_arms', 'blessing', 3, 'Bless Arms', 'For 60 s, their blows do 20% more damage to monsters.', 20, 120, array['self', 'player']::text[], null, '{"more":0.2,"secs":60}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('blessing_kinship', 'blessing', 3, 'Kinship', 'Your next go at taming this wildermon within 60 s is 25 points likelier to succeed.', 20, 600, array['wildermon']::text[], null, '{"points":0.25,"secs":60}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('blessing_benediction', 'blessing', 4, 'Benediction', 'Everybody within 6 tiles of the spot, you too, and every wildermon there heals 20% of their health and stops bleeding.', 30, 120, array['area']::text[], 6, '{"heal":0.2}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('blessing_shield', 'blessing', 4, 'Shield of Dawn', 'For 60 s, damage up to 30% of their health is taken by the shield instead of them.', 30, 180, array['self', 'player']::text[], null, '{"share":0.3,"secs":60}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('blessing_sanctuary', 'blessing', 4, 'Sanctuary', 'For 30 s, nothing wild starts a hunt on anybody within 4 tiles of the spot, and whatever is hunting somebody there gives it up.', 34, 300, array['area']::text[], 4, '{"secs":30}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('blessing_second_life', 'blessing', 5, 'Second Life', 'For 10 minutes, the first blow that would kill them leaves them at 50% of their health instead.', 60, 1800, array['self', 'player']::text[], null, '{"secs":600,"heal":0.5}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('blessing_radiance', 'blessing', 5, 'Radiance', 'For 30 s, every creature within 8 tiles of the spot that is hunting somebody loses 2% of its health a second, 60% in all; it is never killed by it.', 60, 600, array['area']::text[], 8, '{"each":0.02,"secs":30}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('blessing_land', 'blessing', 5, 'Bless the Land', 'Every tree within 10 tiles of the spot grows a stage: sapling to young, young to mature, mature to old and old to very old. One that would grow into dying, and one that is clipped, stays as it is.', 50, 3600, array['area']::text[], 10, '{}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('justice_mark', 'justice', 1, 'Mark of Judgment', 'For 30 s the creature takes 15% more damage from every blow, whoever or whatever strikes it.', 10, 30, array['enemy']::text[], null, '{"more":0.15,"secs":30}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('justice_retribution', 'justice', 1, 'Retribution', 'For 60 s, 20% of every blow that lands on them is dealt back to whatever struck.', 10, 60, array['self', 'player']::text[], null, '{"share":0.2,"secs":60}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('justice_assay', 'justice', 1, 'Assay', 'Every ore seam under the ground within 8 tiles of the spot is marked for you for 10 minutes, as a prospector''s sensing marks it.', 12, 600, array['area']::text[], 8, '{"secs":600}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('justice_sentence', 'justice', 2, 'Sentence', 'Strikes the creature for 25% of the health it has already lost. Not on a creature that is unhurt.', 16, 60, array['enemy']::text[], null, '{"share":0.25}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('justice_bind', 'justice', 2, 'Bind', 'Holds the creature where it stands for 5 s: it neither moves nor strikes. A monster is held for 2.5 s.', 14, 90, array['enemy']::text[], null, '{"secs":5,"monster":0.5}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('justice_equity', 'justice', 2, 'Equity', 'You and the other person both end at the average of your healths.', 10, 60, array['player']::text[], null, '{}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('justice_verdict', 'justice', 3, 'Verdict', 'A creature below 20% of its health dies at once, a monster below 10%; any other loses 10% of its health.', 24, 120, array['enemy']::text[], null, '{"below":0.2,"monster":0.1,"share":0.1}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('justice_summons', 'justice', 3, 'Summons', 'The creature turns on you and hunts only you for 20 s, whoever it was after.', 20, 60, array['enemy']::text[], null, '{"secs":20}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('justice_temper', 'justice', 3, 'Temper', 'For 30 minutes, the thing takes no wear at all while you carry it.', 20, 600, array['object']::text[], null, '{"secs":1800}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('justice_judgment', 'justice', 4, 'Judgment', 'Every creature within 6 tiles of the spot that is hunting somebody loses 15% of its health and, for 30 s, takes 15% more damage from every blow.', 34, 300, array['area']::text[], 6, '{"share":0.15,"more":0.15,"secs":30}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('justice_truce', 'justice', 4, 'Truce', 'For 30 s, nothing within 8 tiles of the spot can strike or be struck, people and creatures alike.', 30, 600, array['area']::text[], 8, '{"secs":30}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('justice_restitution', 'justice', 4, 'Restitution', 'Everything in their latest grave comes back into their pack, wherever they are.', 40, 3600, array['self', 'player']::text[], null, '{}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('justice_execution', 'justice', 5, 'Execution', 'A creature below 50% of its health dies at once, a monster below 30%; any other loses 20% of its health.', 60, 1800, array['enemy']::text[], null, '{"below":0.5,"monster":0.3,"share":0.2}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('justice_oath', 'justice', 5, 'Oath', 'For 10 minutes, every blow that lands on you or on the friend it is cast on is split evenly between you. Only on a friend.', 50, 3600, array['player']::text[], null, '{"secs":600}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('justice_reward', 'justice', 5, 'Due Reward', 'For 30 minutes, every skill they raise gains 20% more.', 50, 3600, array['self', 'player']::text[], null, '{"more":0.2,"secs":1800}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('chaos_hex', 'chaos', 1, 'Hex', 'The creature bleeds 2% of its health a second for 15 s, 30% in all. Bleeding never kills.', 8, 20, array['enemy']::text[], null, '{"each":0.02,"secs":15}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('chaos_fright', 'chaos', 1, 'Fright', 'The creature flees from you for 8 s. Monsters are not frightened.', 10, 60, array['enemy']::text[], null, '{"secs":8}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('chaos_blood_price', 'chaos', 1, 'Blood Price', 'Costs no favour. Spend 20% of your health for 15 favour; not with less than 30% of your health.', 0, 300, array['self']::text[], null, '{"price":0.2,"favour":15,"floor":0.3}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('chaos_siphon', 'chaos', 2, 'Siphon', 'Takes 10% of the creature''s health, and heals you by what a blow of that much would take from you.', 12, 30, array['enemy']::text[], null, '{"share":0.1}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('chaos_cower', 'chaos', 2, 'Cower', 'For 30 s the creature''s blows do 30% less damage.', 14, 60, array['enemy']::text[], null, '{"cut":0.3,"secs":30}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('chaos_pact', 'chaos', 2, 'Pact', 'Costs no favour. Spend 30% of your health: for 60 s your blows do 40% more damage.', 0, 180, array['self']::text[], null, '{"price":0.3,"more":0.4,"secs":60}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('chaos_plague', 'chaos', 3, 'Plague', 'Every wild creature within 5 tiles of the spot bleeds 1.5% of its health a second for 30 s, 45% in all. Bleeding never kills.', 26, 180, array['area']::text[], 5, '{"each":0.015,"secs":30}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('chaos_panic', 'chaos', 3, 'Panic', 'Every wild creature within 6 tiles of the spot flees from it for 10 s, a monster for 3 s.', 24, 120, array['area']::text[], 6, '{"secs":10,"monster":3}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('chaos_unmake', 'chaos', 3, 'Unmake', 'Costs no favour. Destroys a thing you carry and gives you favour of 25% of its quality, 25 at most. Not a thing you wear, a locked thing, or a bag with anything in it.', 0, 600, array['object']::text[], null, '{"per":0.25,"most":25}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('chaos_soul_rend', 'chaos', 4, 'Soul Rend', 'Takes 30% of the creature''s health; if that kills it, 30 favour comes back to you.', 36, 300, array['enemy']::text[], null, '{"share":0.3,"favour":30}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('chaos_shroud', 'chaos', 4, 'Shroud', 'For 60 s nothing notices you from further than 3 tiles off, and whatever is hunting you from further than that loses you.', 30, 300, array['self']::text[], null, '{"reach":3,"secs":60}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('chaos_blood_feast', 'chaos', 4, 'Blood Feast', 'Costs no favour. Spend 15% of your health: for 60 s, every blow you land heals you by 25% of what it dealt.', 0, 600, array['self']::text[], null, '{"price":0.15,"share":0.25,"secs":60}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('chaos_cataclysm', 'chaos', 5, 'Cataclysm', 'Every wild creature within 8 tiles of the spot loses 40% of its health at once.', 70, 1800, array['area']::text[], 8, '{"share":0.4}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('chaos_abyssal_gaze', 'chaos', 5, 'Abyssal Gaze', 'The creature flees from you for 15 s, monsters too, and takes 50% more damage from every blow while it does.', 60, 1800, array['enemy']::text[], null, '{"secs":15,"more":0.5}');
insert into faith_spell (id, patron, tier, name, note, cost, rest, on_what, radius, fx) values ('chaos_undying', 'chaos', 5, 'Undying', 'Costs no favour. Spend 25% of your health: for 60 s no blow can kill you, and one that would leaves you at 1% of your health.', 0, 3600, array['self']::text[], null, '{"price":0.25,"secs":60,"floor":0.01}');
