insert into school_def values ('kindling', 'Kindling', 'kindling', 'Heat, out of the warm stones. What it touches burns, and goes on burning.');
insert into school_stone values ('kindling', 'garnet', 0);
insert into school_stone values ('kindling', 'ruby', 1);
insert into school_def values ('binding', 'Binding', 'binding', 'Stillness, out of the clear stones. What it touches stops, and stays stopped.');
insert into school_stone values ('binding', 'sapphire', 0);
insert into school_stone values ('binding', 'diamond', 1);
insert into school_def values ('warding', 'Warding', 'warding', 'A skin, out of the soft stones. It stands between a blow and whoever it was aimed at.');
insert into school_stone values ('warding', 'topaz', 0);
insert into school_stone values ('warding', 'emerald', 1);
insert into spell_def values ('ember', 'kindling', 'Ember', 1, 'garnet', 3, 12, 0, 5, 'creature', 'A coal out of the stone, put where you are looking.', 'The garnet goes cold in your hand and the {t} is burning. ({n})');
insert into spell_def values ('pyre', 'kindling', 'Pyre', 30, 'ruby', 7, 9, 0, 3, 'around', 'Everything close enough to feel it, at once.', 'The air goes white and everything near you is alight. ({n})');
insert into spell_def values ('snare', 'binding', 'Snare', 1, 'sapphire', 3, 0, 8, 5, 'creature', 'One thing, standing exactly where it is.', 'The {t} puts a foot down and does not pick it up again. ({n})');
insert into spell_def values ('stillfield', 'binding', 'Still field', 30, 'diamond', 7, 0, 5, 3, 'around', 'Everything close enough, for rather less time each.', 'Everything around you stops where it stands. ({n})');
insert into spell_def values ('aegis', 'warding', 'Aegis', 1, 'topaz', 4, 20, 0, 0, 'self', 'A skin over you that takes the blows instead, until it is used up.', 'Something closes over you, a half inch out from the skin. ({n})');
insert into spell_def values ('bulwark', 'warding', 'Bulwark', 30, 'emerald', 8, 16, 0, 3, 'around', 'The same skin, over everybody standing near you.', 'It closes over everybody within reach of you. ({n})');
insert into rite_def values ('ward', 'blade', 'Ward', 20, 10, 30, 900, '{"guard":1.6}', 'You set your feet and the shield stops being a thing you are holding.', 'Damage stopped by shield and armour +60% for 30s. 15m before it may be called again.');
insert into rite_def values ('redhour', 'berserker', 'Red Hour', 24, 12, 30, 1200, '{"edge":1.5,"guard":0.7}', 'It goes red at the edges, and you stop minding what lands on you.', 'Damage per hit +50%, damage stopped by shield and armour −30% for 30s. 20m before it may be called again.');
insert into rite_def values ('set', 'pikeman', 'Set', 20, 10, 45, 900, '{"guard":1.4,"aim":1.15}', 'You set the butt of it in the ground and the line stops where you are.', 'Damage stopped by shield and armour +40%, chance to hit +15% for 45s. 15m before it may be called again.');
insert into rite_def values ('farsight', 'archer', 'Farsight', 22, 14, 45, 900, '{"aim":1.3,"edge":1.2}', 'The far end of the field comes close enough to touch.', 'Chance to hit +30%, damage per hit +20% for 45s. 15m before it may be called again.');
insert into rite_def values ('quickhand', 'skirmisher', 'Quick Hand', 18, 8, 30, 720, '{"hands":0.7}', 'Your hands get ahead of you and you let them.', 'Time per action −30% for 30s. 12m before it may be called again.');
insert into rite_def values ('staunch', 'chirurgeon', 'Staunch', 26, 16, 60, 1200, '{"knit":3}', 'You get your hands on it and it begins closing under them.', 'Wound healing speed +200% for 60s. 20m before it may be called again.');
insert into rite_def values ('pack', 'beastmaster', 'Call the Pack', 28, 18, 60, 1200, '{"fang":1.5,"hide":1.3}', 'You say the word and everything that answers to you stops being tame.', 'Damage dealt by creatures you keep +50%, maximum health of creatures you keep +30% for 60s. 20m before it may be called again.');
insert into rite_def values ('whiteheat', 'kindler', 'White Heat', 22, 12, 30, 900, '{"force":1.6}', 'The stone goes hot enough to hurt and you hold on to it anyway.', 'Spell damage, hold and skin +60% for 30s. 15m before it may be called again.');
insert into rite_def values ('longhold', 'binder', 'Long Hold', 24, 14, 45, 900, '{"force":1.4,"reach":1.4}', 'The air goes thick and slow as far out as you can see.', 'Spell damage, hold and skin +40%, spell range +40% for 45s. 15m before it may be called again.');
insert into rite_def values ('deepstone', 'warder', 'Deep Stone', 26, 16, 60, 1200, '{"thrift":0.35}', 'You reach further into it than you have any business reaching, and it lets you.', 'Stone wear per cast −65% for 60s. 20m before it may be called again.');
insert into path_def values ('love', 'Love', 'The gardener’s way. Things grow for you, things trust you, and what is hurt mends.');
insert into path_step values ('love', 1, 3, 'Green thumb', 'A stage of anything sown on your settlement takes a fifth less time.', null, null, null);
insert into path_step values ('love', 2, 12, 'Refresh', 'Hunger and thirst, both full, in a breath.', 'refresh', 1200, 'You are neither hungry nor thirsty.');
insert into path_step values ('love', 3, 25, 'Gentle hand', 'Your chance to tame anything is a quarter higher.', null, null, null);
insert into path_step values ('love', 4, 45, 'Mend the flesh', 'Everything open on you closes, and two fifths of your health comes back.', 'mendflesh', 2400, 'Wounds closed.');
insert into path_step values ('love', 5, 70, 'Abundance', 'A harvest gives 34% more than it did.', null, null, null);
insert into path_def values ('knowledge', 'Knowledge', 'The reader’s way. The work goes in faster, you see further, and you can read what is in front of you.');
insert into path_step values ('knowledge', 1, 3, 'Attentive', 'Everything you do teaches you a tenth more, for good.', null, null, null);
insert into path_step values ('knowledge', 2, 12, 'Sense the rock', 'What metal is under the ground within fifteen tiles, all at once.', 'sense', 900, 'The ground gives up what is in it.');
insert into path_step values ('knowledge', 3, 25, 'Reader', 'You read the blood of any wildermon at a glance, whatever your husbandry.', null, null, null);
insert into path_step values ('knowledge', 4, 45, 'Recall the way', 'You are standing at your own token, however far off you had got.', 'recall', 2400, 'Home.');
insert into path_step values ('knowledge', 5, 70, 'Keen sight', 'You see a quarter further than anybody else on the island.', null, null, null);
insert into path_def values ('power', 'Power', 'The plain way. You carry more, you hit harder, and less of what is aimed at you lands.');
insert into path_step values ('power', 1, 3, 'Strong back', 'Armour, and a load past what your back will take, burden you a fifth less.', null, null, null);
insert into path_step values ('power', 2, 12, 'Second wind', 'Your wind comes back all at once.', 'secondwind', 720, 'Wind back.');
insert into path_step values ('power', 3, 25, 'Hard hands', 'You hit 16% harder with anything, or with nothing.', null, null, null);
insert into path_step values ('power', 4, 45, 'Fury', 'For thirty seconds everything you hit takes twice what it would.', 'fury', 2400, 'Fury.');
insert into path_step values ('power', 5, 70, 'Ironhide', 'What you are wearing turns a tenth more of every blow.', null, null, null);
