update item_def set description = 'Cut off a lavender bush with a sickle. Boiled, it gives a violet.' where id = 'lavender';
update item_def set description = 'Picked off grass in flower, a wildflower for every clump. Eight of them and a bucket of lye boil into orange dye, for cloth, leather, a banner or a sail.' where id = 'wildflowers';
update item_def set description = 'A water lily flower, picked off one planted in still water. Boiled, it gives the only white there is.' where id = 'water_lily';
update item_def set description = 'A lotus flower, picked off one planted in still water. Boiled, it gives a magenta.' where id = 'lotus_flower';
update item_def set description = 'Found by botanizing at the water''s edge. Plant it in still water 0.2 to 2.0 m deep -- a pond, a pool or the shallows of the sea, never where water runs -- and it lays its pads on the water at once. It roots in an hour and then flowers in spring and summer, white or pink, open by day and shut at night; in winter only the root is left under the water, and the pads come up again in spring. A flower picked is gone until the season turns.' where id = 'lily_root';
update item_def set food = 0.03 where id = 'lotus_seed';
update item_def set description = 'Found by botanizing at the water''s edge, and three to a lotus seed head. Eaten raw they fill 3% of the food bar, roasted at a campfire 14%. Planted in still water 0.2 to 2.0 m deep, a seed holds its leaves up out of the water on stalks at once; it roots in an hour and then flowers in summer and carries its seed heads in autumn; in winter only the root is left under the water. What is picked is gone until the season turns.' where id = 'lotus_seed';
update item_def set description = 'A fleece shorn from a living Woola. It grows back, which fur never does.' where id = 'wool';
update item_def set description = 'Wool or cotton spun and woven. Stuffs a mattress and makes what you wear.' where id = 'cloth';
update item_def set description = 'A soft pelt taken from a butchered wildermon.' where id = 'fur';
update item_def set description = 'A raw skin off a carcass. Useless until it has been through lye.' where id = 'hide';
update item_def set description = 'Hide tanned in lye and worked soft. What every leather thing is cut from.' where id = 'leather';
update item_def set description = 'Cut from a carcass for the hook. A fishing bait.' where id = 'offal';
update item_def set food = 0.25 where id = 'broth';
update item_def set description = 'Bones boiled down in water: a little of every kind of food in one bowl.' where id = 'broth';
update item_def set description = 'A small scent gland. Rare, and prized by alchemists.' where id = 'gland';
update item_def set description = 'A straight length of wood, carved from a log. Handles for tools and rails for fences.' where id = 'shaft';
update item_def set description = 'Flat bands of metal, one lump beaten out to a ribbon. Everything that has to hold together under a load is banded with them.' where id = 'ribbon';
update item_def set description = 'A cast axle as long as a cart is wide. A large cart takes one and a wagon two.' where id = 'big_axle';
update item_def set description = 'Spokes, felloes and a metal tyre shrunk on hot. A large cart takes two and a wagon four.' where id = 'large_wheel';
update item_def set description = 'A shaped bar and a leather harness. A wildermon is hitched into one to pull.' where id = 'yoke';
update item_def set drink = 0.3 where id = 'milk_bucket';
update item_def set description = 'Five litres of milk, still warm. Drink it, or work it into cheese while it is fresh.' where id = 'milk_bucket';
update item_def set food = 0.3 where id = 'cheese';
update item_def set description = 'Milk pressed and left to itself for a while. It keeps far better than what it was made of.' where id = 'cheese';
update item_def set food = 0.22 where id = 'honey';
update item_def set description = 'Comb honey out of a hive. It keeps almost forever and everything on the island wants it.' where id = 'honey';
update item_def set description = 'Comb rendered down. It is what a candle is, and what a waxed thread is drawn through.' where id = 'wax';
update item_def set description = 'Ribbons of metal, oiled cloth and a handle. With a candle in it and lit at a fire it throws five tiles of light at the roughest and nine at the best, and a candle lasts thirty-nine minutes in a rough one and an hour and thirteen minutes in a fine one.' where id = 'lantern';
update item_def set description = 'A shaft with oiled cloth wound round the head of it. Touch it to a fire and it burns nine minutes to eighteen minutes by how well it was wound, throwing three to five tiles of light.' where id = 'torch';
update item_def set description = 'Wax drawn round a wick. Set one in a lantern and it will show you the ground on the blackest night.' where id = 'candle';
update item_def set description = 'What a Middun leaves behind, which is the best thing that ever happened to a field. Spread it on tilled ground.' where id = 'compost';
update item_def set description = 'A tree of wood under stitched leather, girthed and stirruped. Fit one to an Orse and you can ride it.' where id = 'saddle';
update item_def set description = 'Headstall, bit and reins. Without one there is nothing to steer by.' where id = 'bridle';
update item_def set description = 'Plant it on grass or dirt to grow a tree. Wilts quickly if left lying around.' where id = 'sprout';
update item_def set food = 0.08 where id = 'blueberry';
update item_def set food = 0.08 where id = 'raspberry';
update item_def set food = 0.08 where id = 'strawberry';
update item_def set food = 0.06 where id = 'lingonberry';
update item_def set food = 0.02 where id = 'acorn';
update item_def set food = 0.05 where id = 'nuts';
update item_def set food = 0.18 where id = 'meat';
update item_def set description = 'Raw meat from a butchered wildermon. Raw, it fills 18% of the food bar; cooked at a campfire, 35%.' where id = 'meat';
update item_def set food = 0.35 where id = 'cooked_meat';
update item_def set food = 0.22 where id = 'baked_potato';
update item_def set food = 0.16 where id = 'roast_onion';
update item_def set food = 0.12 where id = 'roast_nuts';
update item_def set food = 0.14 where id = 'roast_lotus_seeds';
update item_def set food = 0.3 where id = 'berry_compote';
update item_def set description = 'Berries stewed down in a bowl over a fire.' where id = 'berry_compote';
update item_def set food = 0.75 where id = 'stew';
update item_def set description = 'Meat and vegetables simmered together. The best meal a campfire can make.' where id = 'stew';
update item_def set food = 0.6 where id = 'pottage';
update item_def set description = 'A thick pot of vegetables and grain, simmered down slowly.' where id = 'pottage';
update item_def set food = 0.42 where id = 'bread';
update item_def set description = 'A baked loaf. The first food that keeps and travels.' where id = 'bread';
update item_def set food = 0.32 where id = 'porridge';
update item_def set description = 'Cornmeal boiled thick in a bowl.' where id = 'porridge';
update item_def set food = 0.28 where id = 'preserves';
update item_def set description = 'Berries put up in a sealed jar. They keep for a very long time.' where id = 'preserves';
update item_def set description = 'Wheat ground on a quern. Wet it and it becomes dough. Keeps in a larder or a craft material bin.' where id = 'flour';
update item_def set description = 'Corn ground coarse. Boiled up it makes porridge. Keeps in a larder or a craft material bin.' where id = 'cornmeal';
update item_def set description = 'Flour and water worked together. It wants a fire under it. Keeps in a larder or a craft material bin.' where id = 'dough';
update item_def set description = 'A strip of cloth for binding a wound. One strip, one wound.' where id = 'bandage';
update item_def set description = 'Cut from a reed bed. Soaked and pressed it becomes papyrus.' where id = 'reed';
update item_def set description = 'A pressed sheet, smooth enough to take ink.' where id = 'papyrus';
update item_def set description = 'Soot, gland and lye water, ground together until it flows black.' where id = 'ink';
update item_def set description = 'Papyrus sewn between leather boards. Reading it sharpens the head, and wears the pages.' where id = 'book';
update item_def set description = 'A book written on one trade, its name on the spine. Studied, it teaches that trade where a plain book teaches mind logic, and wears the pages as a plain one does.' where id = 'trade_book';
update item_def set description = 'A broken piece of something old. Find the rest of it and a restorer can put it back together. Nothing repairs it before then, and if it breaks first it is gone.' where id = 'fragment';
update item_def set description = 'A square of oiled hide with a stretch of country drawn on it and no names anywhere. Read it to see the picture; walk until the ground matches, then dig. Something is always left to watch over a hoard. Keep it in a pack or a crate — left lying in a field it will rot, and take the hoard with it.' where id = 'treasure_map';
update item_def set description = 'A small figure in worn stone, carried by people who are long gone.' where id = 'statuette';
update item_def set description = 'Gives nothing until it is restored. Restore it (restoration: difficulty 15 for a minor one, 30 major, 45 ancient) and what it gives is rolled then, with its rarity. Nothing repairs it before then, and if it breaks first it is gone.' where id = 'tarnished_bauble';
update item_def set description = 'Set it into one of the 21 minor sockets of the altar of a settlement of yours. Every citizen of that settlement, while working on it, then gets what is written on it: less time per action, or more skill gained, in that one skill.' where id = 'bauble_minor';
update item_def set description = 'Set it into one of the 5 major sockets of the altar of a settlement of yours. Every citizen of that settlement, while working on it, then has the chance written on it of twice the yield from each action in that one skill.' where id = 'bauble_major';
update item_def set description = 'Undoes one of your trades. In the Trades window, Undo on your crafting or your fighting trade puts it down as though you had never taken it up, clears its tree, and uses this up; the next trade you take up in its place costs nothing, where a change costs 500 silver. Only on an island, where trades are kept.' where id = 'bauble_regret';
update item_def set description = 'Left by 1% of sacrifices at an altar, with the rarity of what was given up. Absorb it into an ordinary thing in your pack (Absorb into, on the mote) and that thing, or one of it where it is a stack, takes the mote''s rarity. The mote is used up.' where id = 'mote';
update item_def set description = 'Set it into one of the 3 ancient sockets of the altar of a settlement of yours. Every citizen of that settlement, while working on it, then gets what is written on it added to every yield of that one action.' where id = 'bauble_ancient';
update item_def set description = 'A closed clay lamp with a wick hole. It still smells faintly of oil.' where id = 'old_lamp';
update item_def set description = 'A disc of bronze polished on one face. It gives back a dim, honest likeness.' where id = 'bronze_mirror';
update item_def set description = 'Fine teeth cut in old bone. Somebody took a great deal of trouble over it.' where id = 'bone_comb';
update item_def set description = 'Cutting a grass tile gives two; plant 10 of it on a tile of dirt and the tile is grass.' where id = 'mixed_grass';
update item_def set food = 0.01 where id = 'sage';
update item_def set food = 0.01 where id = 'basil';
update item_def set food = 0.01 where id = 'thyme';
update item_def set food = 0.01 where id = 'mint';
update item_def set food = 0.01 where id = 'rosemary';
update item_def set food = 0.1 where id = 'potato';
update item_def set food = 0.08 where id = 'carrot';
update item_def set food = 0.12 where id = 'cabbage';
update item_def set food = 0.05 where id = 'wheat';
update item_def set food = 0.11 where id = 'corn';
update item_def set description = 'A belt of loops and pouches. Wear it and it carries the jobs you do most, ready to hand: one loop for every ten points of how well it was made.' where id = 'toolbelt';
update item_def set description = 'Woven wide enough to sit on cross-legged. Lay it down somewhere quiet and think about nothing.' where id = 'rug';
update item_def set description = 'Tusk laid along the belly, sinew glued along the back, both off something that was trying to kill you. Seventeen tiles, 21 damage before skill and quality, and a shot every 3.6 seconds.' where id = 'composite_bow';
update item_def set description = 'Dragon scale riveted to a leather cap.' where id = 'scale_helm';
update item_def set description = 'Dragon scale laid in courses over a leather body. It turns more than plate and weighs less than chain.' where id = 'scale_cuirass';
update item_def set description = 'Dragon scale on the outside of the arm.' where id = 'scale_sleeves';
update item_def set description = 'Dragon scale down the thigh and shin.' where id = 'scale_leggings';
update item_def set description = 'Dragon scale over the instep.' where id = 'scale_boots';
update item_def set description = 'Cut from the jaw of something that meant to use it on you. Hard, close-grained and springy: the belly of a composite bow is made of it.' where id = 'tusk';
update item_def set description = 'Dried back-strap. It pulls like nothing that grows and it is what the back of a composite bow is laid with.' where id = 'sinew';
update item_def set description = 'A plate the size of your hand, warm to hold and lighter than it looks. Nothing on this island turns a blow like it, and there is only one place to get one.' where id = 'dragon_scale';
update item_def set description = 'Turned out of damp dirt with a shovel. The first bait anybody uses, and the one that never stops working on small fish.' where id = 'worm';
update item_def set description = 'Yarn knotted to a rope headline. Dragged through shallow water it takes a great many small fish at once and lets the big ones through.' where id = 'fishing_net';
update item_def set description = 'A woven basket trap with a throat it is easy to swim into and hard to swim out of. Set it in water, bait it, and leave it.' where id = 'creel';
update item_def set description = 'A noose of rope on a bent shaft. Set it out in the country, bait it, and come back to whatever came to the bait.' where id = 'snare';
update item_def set description = 'A weighted board on a trigger. It holds very nearly anything that walks, and it is a great deal of work to build.' where id = 'deadfall';
update item_def set stamina = 0.2 where id = 'herb_tea';
update item_def set description = 'Herbs steeped in water, a cup of it. Drunk, it puts back 20% of your stamina.' where id = 'herb_tea';
update item_def set description = 'Herbs worked into beeswax. Rubbed in over a dressing, it keeps the wound under it from going bad until it closes.' where id = 'salve';
update item_def set description = 'Herbs steeped down to a few bitter drops. Taken, foraging, botanizing, alchemy and first aid each go in 10% faster for fifty minutes.' where id = 'tincture';
update item_def set description = 'Herbs worked into cotton. Laid on the wound it suits, it stops the bleeding, keeps the dirt out and closes it 2.3 times as fast as cloth.' where id = 'cover';
update item_def set description = 'A pot of colour, struck with lye so it bites and holds. One pot does one thing.' where id = 'dye';
update item_def set description = 'Cloth on a staff. Plant it on the deed and fly your colour over it.' where id = 'banner';
update item_def set description = 'A flag on a tall pole. Set it up and the flag flies down the wind, out straight in a gale and hanging in a calm; dye it first and it flies your colour, and on a settlement it carries the settlement''s device.' where id = 'flagpole';
update item_def set description = 'A timber arch a tile across with a climbing rose at each foot. Set it over a path and walk through it. An arch''s roses are in leaf one day after it is set down, in bud two days after and in flower three days after, in spring and summer; the rest of the year a grown arch is in leaf. Picking an arch up and setting it down again starts its roses again.' where id = 'rose_arch';
update item_def set description = 'A stone arch a tile across with a climbing rose at each foot. Set it over a path and walk through it. An arch''s roses are in leaf one day after it is set down, in bud two days after and in flower three days after, in spring and summer; the rest of the year a grown arch is in leaf. Picking an arch up and setting it down again starts its roses again.' where id = 'stone_rose_arch';
update item_def set description = 'Four wemp fibres laid up on a rope tool. Everything that has to hold, hold fast or haul is roped.' where id = 'rope';
update item_def set description = 'Three ropes laid up again into a hawser. It moors a hull, hangs a bucket down a shaft and carries a span of bridge.' where id = 'thick_rope';
update item_def set food = 0.06 where id = 'onion';
update item_def set description = 'Something dead. Butcher it before it rots: meat, fur, leather, bone and glands off a wildermon, and off one of the bad things, tusk, sinew and worse.' where id = 'corpse';
update item_def set description = 'Three legs and a seat. Set it down anywhere.' where id = 'stool';
update item_def set description = 'A board across two posts, made to be written on. Set it up and give it a name, and the name stands there for anyone walking past.' where id = 'sign';
update item_def set description = 'A board wide enough to write a sentence on. Set it up where a road forks and nobody need guess again.' where id = 'great_sign';
update item_def set description = 'A chair with a proper back to it. Set it down anywhere.' where id = 'chair';
update item_def set description = 'A long plank seat on legs. Set it down anywhere.' where id = 'bench';
update item_def set description = 'A square table on four legs.' where id = 'table';
update item_def set description = 'The table a hall is built around.' where id = 'long_table';
update item_def set description = 'A desk with drawers under the top. Holds 20 things.' where id = 'desk';
update item_def set description = 'A bed with a stuffed mattress on it.' where id = 'bed';
update item_def set description = 'A narrow bed for a narrow room.' where id = 'cot';
update item_def set description = 'Sleep in it at night: 50% of the rest a bed of the same QL gives.' where id = 'tent';
update item_def set description = 'A banded chest. Holds 60 things.' where id = 'chest';
update item_def set description = 'A small strongbox. Holds 25 things.' where id = 'coffer';
update item_def set description = 'A cupboard with doors on it. Holds 80 things.' where id = 'cupboard';
update item_def set description = 'Tall enough to hang a cloak full length. Holds 100 things.' where id = 'wardrobe';
update item_def set description = 'A long open rack of shelves. Holds 120 things.' where id = 'shelves';
update item_def set description = 'Shelves with a back and a cornice. Holds 90 things.' where id = 'bookshelf';
update item_def set description = 'A deep cool cupboard for a kitchen. Holds 250 things: food, drink, and the flour, dough and cornmeal a kitchen bakes from.' where id = 'larder';
update item_def set description = 'A decked rack two spots across and four deep. It holds nothing itself: eight plank crates stand on it, each its own crate, and you can see across a warehouse how many are full.' where id = 'crate_shelf';
update item_def set description = 'Staves and hoops. Holds 80 litres of one liquid, and nothing solid.' where id = 'barrel';
update item_def set description = 'Holds one wildermon. With a wildermon already following you, one more is tamed only into an empty crate in your pack. Set down, it shows who is inside; open it to have them follow you or work the deed. It does not rot.' where id = 'creature_crate';
update item_def set description = 'A slanted stand to read from.' where id = 'lectern';
update item_def set description = 'Pegs on a post, by the door.' where id = 'coat_rack';
update item_def set description = 'A box of earth one crop grows in, set down indoors or out: sown, tended and harvested like a field, from the same seeds to the same yields, at a quarter of the crop''s own pace in every season, winter too.' where id = 'planter';
update item_def set description = 'Keeps the wood off the wet ground. Holds 40 things.' where id = 'firewood_rack';
update item_def set description = 'A squared timber post with an iron arm off its head. Set it down and hang a lantern of yours on it: the lantern throws its own reach for everybody at night, five tiles at the roughest and nine at the best, and a candle in it burns as long as in that lantern in your hand, thirty-nine minutes to an hour and thirteen minutes. It is lit, put out and given a candle as a lantern is.' where id = 'lamp_post';
update item_def set description = 'A coursed stone pillar with an iron cage in its top. Set it down and stand a lantern of yours in it: the lantern throws its own reach for everybody at night, five tiles at the roughest and nine at the best, and a candle in it burns as long as in that lantern in your hand, thirty-nine minutes to an hour and thirteen minutes. It is lit, put out and given a candle as a lantern is.' where id = 'lamp_pillar';
update item_def set drink = 0.4 where id = 'ale_bucket';
update item_def set description = 'Thin, sour and honest. Drink it and the work goes easier for a good while.' where id = 'ale_bucket';
update item_def set drink = 0.45 where id = 'cider_bucket';
update item_def set description = 'Pressed apples gone dangerous. A trade comes easier after it.' where id = 'cider_bucket';
update item_def set drink = 0.5 where id = 'juice_bucket';
update item_def set description = 'Fruit pressed under a quern, sweet and cloudy, with nothing dangerous in it. Drink it while it is fresh.' where id = 'juice_bucket';
update item_def set drink = 0.5 where id = 'mead_bucket';
update item_def set description = 'Honey and time. The best thing to come out of a hive after the honey itself.' where id = 'mead_bucket';
update item_def set drink = 0.5 where id = 'wine_bucket';
update item_def set description = 'Cherries, water and an hour and fifty-three minutes of patience.' where id = 'wine_bucket';
update item_def set drink = 0.5 where id = 'spirit_bucket';
update item_def set knack = 3 where id = 'spirit_bucket';
update item_def set description = 'A brew boiled off and caught again. A drink of it gives a knack that lasts three times as long as a drink of mead or wine at the same QL.' where id = 'spirit_bucket';
update item_def set description = 'Two shafts spliced, a waxed line and a strip of metal bent into a hook. Stand at water and fish.' where id = 'fishing_rod';
update item_def set food = 0.06 where id = 'minnow';
update item_def set description = 'A finger of silver. Bait, if you are honest about it.' where id = 'minnow';
update item_def set food = 0.2 where id = 'perch';
update item_def set description = 'Striped and spiny and everywhere there is water with a foot of depth.' where id = 'perch';
update item_def set food = 0.34 where id = 'trout';
update item_def set description = 'Runs where the water is properly deep. Worth cooking properly.' where id = 'trout';
update item_def set food = 0.55 where id = 'pike';
update item_def set description = 'All teeth and bad temper. It takes a good hand to land one.' where id = 'pike';
update item_def set food = 0.85 where id = 'sturgeon';
update item_def set description = 'The deep water fish. Most people fish for a lifetime and never see one.' where id = 'sturgeon';
update item_def set food = 0.52 where id = 'cooked_fish';
update item_def set description = 'Fish over a fire, which is what fish is for.' where id = 'cooked_fish';
update item_def set food = 0.16 where id = 'apple';
update item_def set description = 'Picked off the tree. Keeps a while, bakes into a pie, and presses into cider.' where id = 'apple';
update item_def set food = 0.07 where id = 'cherry';
update item_def set description = 'Sweet and gone in a moment. Better preserved than eaten by the handful.' where id = 'cherry';
update item_def set food = 0.09 where id = 'olive';
update item_def set description = 'Bitter off the branch and worth a great deal pressed.' where id = 'olive';
update item_def set food = 0.15 where id = 'pear';
update item_def set description = 'Sweet and soft when it is ready and gritty the day before. The Crescent''s own.' where id = 'pear';
update item_def set food = 0.08 where id = 'plum';
update item_def set description = 'Dark and sharp-skinned, off the one tree that bears in the cold north.' where id = 'plum';
update item_def set food = 0.12 where id = 'peach';
update item_def set description = 'Downy and dripping. It does not keep: eat it where you picked it, on Middle Isle.' where id = 'peach';
update item_def set food = 0.1 where id = 'fig';
update item_def set description = 'Split and honeyed inside. The skerry''s own, off a tree that likes bare rock.' where id = 'fig';
update item_def set food = 0.04 where id = 'lemon';
update item_def set description = 'Too sour to eat by the handful and worth a great deal to a cook. Grows on the volcano''s warm slopes.' where id = 'lemon';
update item_def set food = 0.12 where id = 'pomegranate';
update item_def set description = 'A leather husk full of red seeds, from the dry steppe. Keeps for weeks.' where id = 'pomegranate';
update item_def set food = 0.08 where id = 'apricot';
update item_def set description = 'Small, golden and gone in a bite, off a steppe tree that wants a dry summer.' where id = 'apricot';
update item_def set food = 0.1 where id = 'quince';
update item_def set description = 'Hard, yellow and sour raw; it wants cooking. Grows on the Crescent beside the pear.' where id = 'quince';
update item_def set food = 0.3 where id = 'olive_oil';
update item_def set description = 'Pressed from olives under a quern. Keeps almost indefinitely and makes anything cooked in it better.' where id = 'olive_oil';
update item_def set food = 0.62 where id = 'apple_pie';
update item_def set description = 'Pastry over stewed apple, baked in an oven. As good as food gets on this island.' where id = 'apple_pie';
update item_def set description = 'A cloth sack. Holds 40 things, and what is in it rots at four fifths the rate if it is left on the ground.' where id = 'sack';
update item_def set holds = 40 where id = 'sack';
update item_def set shelter = 0.8 where id = 'sack';
update item_def set description = 'A stitched leather satchel with a flap. Holds 25 things, and what is in it rots at half the rate if you leave it lying about.' where id = 'satchel';
update item_def set holds = 25 where id = 'satchel';
update item_def set shelter = 0.5 where id = 'satchel';
update item_def set description = 'A deep leather pack on ribbon straps. Holds 60 things, and what is in it rots at two fifths the rate if it is left on the ground. Drop a full one at a work post and it keeps.' where id = 'backpack';
update item_def set holds = 60 where id = 'backpack';
update item_def set shelter = 0.4 where id = 'backpack';
update item_def set description = 'A stake, a crossbar and a strip of metal for a marker. Driven into open ground off your deed, it stands an hour and a quarter to three hours by its quality, and one wildermon will work out of it as it would out of a settlement. When it goes over, the creature comes back to you.' where id = 'work_post';
update item_def set description = 'A pond dug and lined for fish. Set it down on your settlement and it stocks itself at a fish in an hour, up to 10 of them.' where id = 'fish_pond';
update item_def set description = 'A heavy wheel on an upright spindle, kicked round from below. Anybody shaping clay within 2.4 tiles of it takes 30% less time a go.' where id = 'potters_wheel';
update item_def set description = 'Cloth, nails and a plank, made up to put things right away from the bench. Used on anything damaged, it takes 50 damage off it and none of its quality, and is used up.' where id = 'repair_kit';
update item_def set description = 'Tar and beeswax worked together. Worked over a thing it seals it, and a sealed thing never decays wherever it is left. A thing takes one sealant, and a pile one for each thing in it.' where id = 'sealant';
update item_def set description = 'A stack of shallow boxes for a swarm to live in. Set it down on your deed and keep a Vesp there, and it fills itself with honey and beeswax. Holds 40 of them.' where id = 'hive';
update item_def set description = 'A grooved block the strands are laid round and twisted against. Nothing is roped without one.' where id = 'rope_tool';
update item_def set description = 'Spins wool, cotton and wemp into yarn. Stand at it to work.' where id = 'spindle';
update item_def set description = 'Weaves yarn into cloth. Stand at it to work.' where id = 'loom';
update item_def set description = 'A stone smelter, built flat-packed and bedded in where you set it down. Turns ore into lumps, and mixes alloys. It stands on your own deed.' where id = 'smelter';
update item_def set description = 'A brick kiln for firing clay. Set it down anywhere dry and flat; take it up again when it is cold and empty.' where id = 'kiln';
update item_def set description = 'A bread oven of brick and mortar. Feed it wood, light it, and cook at it as you would a fire — only it does not burn the dinner.' where id = 'oven';
update item_def set description = 'A lined shaft with a windlass over it. It draws its own water, faster the better it was sunk, and holds 50 litres.' where id = 'well';
update item_def set description = 'Basins of stone one over another on a column, the water welling over the top one and spilling round each into the next. It is a well to everything: it draws its own water as a well does, 0.7 litres a minute at the least and 4.0 at quality 100, and holds 50 litres; fill a bucket or a waterskin at it, or drink from it where you stand.' where id = 'fountain';
update item_def set description = 'A deep bin for raw materials: ore, logs, dirt, shards, hides. Holds 400, and nothing a bench has touched.' where id = 'bulk_bin';
update item_def set description = 'A deep bin for worked materials: planks, nails, ribbons, hinges, lumps, bricks. It does not count what is in it — it weighs it, and holds 2500 kg of whatever a bench has turned out.' where id = 'craft_bin';
update item_def set description = 'A bin with a tight lid for seed. It weighs what is in it rather than counting it: 100 kg, which is 5000 wheat seeds or 1000 seed potatoes.' where id = 'seed_bin';
update item_def set description = 'A bin with a damp cloth under the lid, for sprouts. It weighs what is in it rather than counting it: 100 kg, which is 1000 sprouts.' where id = 'sprout_bin';
update item_def set description = 'An open crate with a rotten bottom. Anything put in it rots thirty times faster than it would in the rain.' where id = 'trash_crate';
update item_def set description = 'A pair of shafts on wheels. Take hold of it and it follows you about, carrying 100 things you do not have to.' where id = 'cart';
update item_def set description = 'A cart on two large wheels, with a box body and a seat over the axle. It holds 1000 things of any weight, and nothing under a hitched wildermon will move it.' where id = 'large_cart';
update item_def set description = 'Four wheels, two axles and a bed you could sleep a family on. It holds 10000 things of any weight, and it does not roll until all four yokes have a wildermon in them.' where id = 'wagon';
update item_def set description = 'A clinker hull with a pair of oars in her. Launch her into two deep of water, climb aboard and row. Carries 300 things and you.' where id = 'rowing_boat';
update item_def set description = 'A ship on a whole tile, wanting five deep of water under her. Holds 5000 things and carries three passengers besides whoever has the helm.' where id = 'caravel';
update item_def set description = 'A decked hull with a mast, a sail and a rudder. Four deep of water under her, and she goes where the coast goes. Carries 1500 things.' where id = 'sailing_boat';
update item_def set description = 'Holds 30 litres of one liquid, and nothing solid at all.' where id = 'small_barrel';
update item_def set description = 'Holds 250 litres of one liquid. It takes a while to fill and longer to empty.' where id = 'large_barrel';
